// Items of a topic that the current user may see. Expired / archived items
// come last.
function nbTopicItems(topicId){
  var docs=window.dynamicDocs||{};
  return Object.keys(docs).map(function(k){return docs[k];}).filter(function(d){
    return d&&d.topicIds&&d.topicIds.indexOf(topicId)!==-1&&nbVisible(d);
  }).sort(function(a,b){
    return (nbActive(b)-nbActive(a))||(NB_KIND_ORDER.indexOf(a.kind)-NB_KIND_ORDER.indexOf(b.kind))||nbPlain(a.topic).localeCompare(nbPlain(b.topic),'he');
  });
}
