// ── STATUSES (spec §10) and editorial tracking ──────────────────────────
// Only "published" items are shown to agents. Editors see everything, with
// a badge. An item that was ever published is never permanently deleted.
var NB_STATUSES={
  draft:{label:'טיוטה',color:'#6B7280',bg:'#F1F3F6'},
  pending:{label:'ממתין לאישור',color:'#B45309',bg:'#FEF3E2'},
  published:{label:'פורסם',color:'#0F7A3E',bg:'#EDFAF3'},
  expired:{label:'לא בתוקף',color:'#B42318',bg:'#FDECEA'},
  archived:{label:'ארכיון',color:'#475569',bg:'#E9EDF2'}
};
var NB_STATUS_ORDER=['draft','pending','published','expired','archived'];
// Editorial tracking (from the knowledge-map spreadsheet): content state,
// required action, main source, priority. Editors only.
var NB_TRACK_STATES=['קיים','קיים חלקית','חסר חלקית','חסר','שחר להשלים'];
var NB_PRIORITIES=['גבוהה','בינונית','נמוכה'];

// Read-only users (agents) — set by the demo gate or by WordPress.
function nbIsReadonly(){ return document.body.classList.contains('wkb-readonly'); }
// Whether the current user may see an item in the library, search and flows.
function nbVisible(d){ return !!d&&(!nbIsReadonly()||d.status==='published'); }
// Expired / archived items stay out of the active flows (spec §10).
function nbActive(d){ return !!d&&d.status!=='expired'&&d.status!=='archived'; }
function nbWasPublished(d){ return !!d&&(d.status==='published'||!!d.publishedAt); }
function nbStatusBadge(d,always){
  var s=NB_STATUSES[d&&d.status]||NB_STATUSES.published;
  if(!always&&d.status==='published') return '';
  return '<span class="status-badge" style="color:'+s.color+';background:'+s.bg+'">'+s.label+'</span>';
}

// Brings any library (built-in seed, older saved data, restored history) to
// the current model. Idempotent: safe to run after every load or restore.
//  - old one-document-per-topic links (topic.dynId) become item.topicIds
//  - waves/priorities are dropped (removed from the product)
//  - missing item fields get defaults (type, worlds, tags, description)
function nbNormalizeModel(){
  var docs=window.dynamicDocs=window.dynamicDocs||{};
  TOPICS.forEach(function(t){
    if(t.dynId&&docs[t.dynId]){
      var d=docs[t.dynId];
      d.topicIds=d.topicIds||[];
      if(d.topicIds.indexOf(t.id)===-1) d.topicIds.push(t.id);
    }
    delete t.dynId; delete t.active; delete t.wave; delete t.pri;
    if(t.desc==null) t.desc='';
  });
  Object.keys(docs).forEach(function(k){
    var d=docs[k]; if(!d) return;
    var seed=NB_SEED_META[k];
    if(!d.topicIds) d.topicIds=seed?seed.topics.slice():[];
    if(!NB_KINDS[d.kind]) d.kind=seed?seed.kind:'R';
    if(!Array.isArray(d.worlds)||!d.worlds.length) d.worlds=[NB_CAT_TO_WORLD[d.cat]||'service'];
    if(typeof d.tags==='string') d.tags=d.tags.split(',').map(function(s){return s.trim();}).filter(Boolean);
    if(!Array.isArray(d.tags)) d.tags=[];
    if(d.desc==null) d.desc='';
    if(d.owner==null) d.owner='';
    // Items from before statuses existed were all live: they count as published.
    if(!NB_STATUSES[d.status]) d.status='published';
    if(d.status==='published'&&!d.publishedAt) d.publishedAt=d.updatedAt||d.createdAt||null;
    if(!d.track||typeof d.track!=='object') d.track={};
    delete d.wave;
  });
}
