window.dynamicDocs['pdf_011'] = {"id":"pdf_011","topic":"M-00 · אבחון מרכזי לתקלות ושירות בחו\"ל","cat":"intl","docType":"pdf","kind":"M","desc":"זיהוי מהיר של התקלה בחו\"ל והפניה למסלול הטיפול הנכון (R-01 עד R-05)","tags":["חו\"ל","אבחון","נדידה"],"stages":[],"body":{"intro":["לזהות במהירות מה התקלה של הלקוח ולהפנות למסלול הטיפול הנכון. המסמך מלווה את הנציג בתחילת השיחה בלבד — ברגע שסוג התקלה ברור, עוברים למסלול הטיפול המתאים","כלל מנחה: אין לבצע דיבאג של גלישה, שיחות או הודעות לפני שווידאת שהקו פתוח לשירות בחו\"ל ושהמכשיר רשום לרשת זרה"],"questions":[{"q":"מה לא עובד כרגע — קליטה, גלישה, שיחות או הודעות?","hint":"שלב 1: שאל את הלקוח וסמן את התיאור הראשוני, אך אל תעבור עדיין למסלול התקלה. תחילה יש לוודא שהתנאים הבסיסיים לשירות בחו\"ל תקינים","answers":[{"text":"סימנתי — המשך לבדיקות הבסיס","note":"","go":"q:1"}]},{"q":"האם הקו פתוח לשירותי חו\"ל / נדידה?","hint":"שלב 2: בדיקות בסיס במערכת","answers":[{"text":"כן","note":"","go":"q:2"},{"text":"לא","note":"פתח את השירות בהתאם להרשאות ולתהליך הקיים. לאחר השינוי הנחה את הלקוח לבצע מצב טיסה או כיבוי והדלקה, ובדוק שוב האם המכשיר התחבר לרשת","go":"q:2"}]},{"q":"האם קיימת חבילת חו\"ל בתוקף?","hint":"בדוק: החבילה פעילה, תאריכי החבילה תקינים, המדינה שבה נמצא הלקוח כלולה בחבילה, והחבילה לא נוצלה במלואה","answers":[{"text":"הכול תקין","note":"","go":"q:3"},{"text":"נמצאה בעיה","note":"טפל בהתאם לממצא לפני המשך האבחון","go":"q:3"}]},{"q":"האם מופיע במכשיר שם של רשת סלולרית?","hint":"שלב 3: שאל את הלקוח","answers":[{"text":"מופיעה רשת סלולרית","note":"","go":"q:4"},{"text":"לא מופיעה רשת / מופיע \"אין שירות\"","note":"עצור את אבחון הגלישה, השיחות או ההודעות. רק לאחר שהמכשיר נרשם לרשת ניתן להמשיך לבדוק את השירות שאינו עובד","go":"item:pdf_012"}]},{"q":"איזה שירות אינו עובד?","hint":"שלב 4: לפי מה שהלקוח דיווח בשלב 1. המכשיר רשום לרשת","answers":[{"text":"גלישה","note":"","go":"q:5"},{"text":"הוצאת שיחות","note":"","go":"q:7"},{"text":"קבלת שיחות","note":"","go":"q:8"},{"text":"הודעות SMS","note":"ודא שהמכשיר רשום לרשת, ושאל: \"הבעיה היא בשליחה, בקבלה או בשניהם?\" — המשך לפי סוג התקלה","go":"item:pdf_016"}]},{"q":"ההגדרות במכשיר תקינות?","hint":"בדוק תחילה במכשיר: נתונים סלולריים פעילים, נדידת נתונים פעילה, ובמכשיר עם שני קווים — קו wecom נבחר לגלישה","answers":[{"text":"תקין ועדיין אין גלישה","note":"","go":"q:6"},{"text":"לא תקין","note":"תקן בהתאם למסמך התפעול המתאים (נדידת נתונים וקו לגלישה: O-02) ובדוק שוב","go":"q:5"}]},{"q":"\"הגלישה לא עובדת בכלל, או שרק אפליקציה מסוימת לא עובדת?\"","hint":"","answers":[{"text":"אין גלישה בכלל","note":"","go":"item:pdf_013"},{"text":"רק אפליקציה מסוימת לא עובדת","note":"","go":"item:pdf_014"}]},{"q":"\"אתה מצליח לקבל שיחות?\"","hint":"הלקוח לא מצליח להוציא שיחות. ודא שהמכשיר רשום לרשת","answers":[{"text":"כן","note":"תקלה בשיחות יוצאות בלבד — מסלול א׳ במסמך השיחות","go":"item:pdf_015"},{"text":"לא","note":"קיימת תקלה גם בשיחות יוצאות וגם בשיחות נכנסות. המשך למסלול השיחות בהתאם לממצאים (מסלול ג׳)","go":"item:pdf_015"}]},{"q":"\"אתה מצליח להוציא שיחות?\"","hint":"הלקוח לא מקבל שיחות. ודא שהמכשיר רשום לרשת","answers":[{"text":"כן","note":"תקלה בשיחות נכנסות בלבד — מסלול ב׳ במסמך השיחות","go":"item:pdf_015"},{"text":"לא","note":"קיימת תקלה גם בשיחות נכנסות וגם בשיחות יוצאות. המשך למסלול השיחות בהתאם לממצאים (מסלול ג׳)","go":"item:pdf_015"}]}],"outro":["שלב 5 — לאחר שינוי במערכת: הנחה את הלקוח לבצע מצב טיסה והחזרה למצב רגיל, או כיבוי והדלקת המכשיר","לאחר מכן בדוק שוב: האם המכשיר נרשם לרשת, והאם השירות שבגינו פנה הלקוח עובד","סדר העבודה: מה הלקוח מדווח ← בדיקת שירותי חו\"ל במערכת ← בדיקת חבילה, תוקף ויעד ← האם המכשיר רשום לרשת? (לא: R-01) ← איזה שירות אינו עובד: גלישה R-02 · אפליקציה בלבד R-03 · שיחות R-04 · הודעות R-05"]},"track":{"state":"קיים","source":"4 מסמכי החו\"ל + 22 פריטי הידע","gap":"להוסיף קישורים למסמכי היעד במנהלת","priority":""},"status":"published"};

