window.dynamicDocs['kbd_o10'] = {"id":"kbd_o10","topic":"O-50 · הפעלת SIM פיזי חדש","cat":"sim","docType":"pdf","kind":"O","desc":"איך מפעילים כרטיס SIM פיזי חדש – בהפעלה עצמית באתר או בליווי נציג – ומה לבדוק אחרי ההפעלה.","tags":["SIM"],"owner":"","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 2 פערים מסומנים ⚠ חסר + 1 הערות לבדיקה","source":"טיוטות פריטי ידע / O-50 הפעלת SIM פיזי חדש.docx"},"status":"draft","source":{"name":"O-50 הפעלת SIM פיזי חדש.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/O-50%20%D7%94%D7%A4%D7%A2%D7%9C%D7%AA%20SIM%20%D7%A4%D7%99%D7%96%D7%99%20%D7%97%D7%93%D7%A9.docx?web=1"},"body":{"groups":[{"title":"מתי משתמשים במסמך","steps":[{"text":"לקוח קיבל כרטיס SIM (במשלוח או באיסוף) ומבקש להפעיל אותו.","img":null},{"text":"לקוח התחיל הפעלה באתר ונתקע באחד השלבים.","img":null},{"text":"אם הלקוח מבקש eSIM – לעבור ל-O-51. אם הקו הופעל אבל לא עובד – לעבור ל-O-53.","img":null}]},{"title":"לפני שמתחילים","steps":[{"text":"בעולם השירות כל פעולה מחייבת זיהוי מלא. אם הפונה אינו בעל החשבון – בעל החשבון עולה לשיחה ומאשר את הפעולה.","img":null},{"text":"איקטוב קווים = זיהוי מלא. לא הושלם הזיהוי הנדרש = לא מוסרים מידע ולא מבצעים פעולה.","img":null},{"text":"לוודא שיש ללקוח את כרטיס ה-SIM ביד – יידרש מספר הסים המלא המודפס על הכרטיס.","img":null},{"text":"לוודא שהפרטים שהלקוח יזין זהים לפרטים שנמסרו בהזמנה: ת״ז / ח.פ ו-4 ספרות אחרונות של אמצעי התשלום.","img":null}]},{"title":"הפעלה עצמית באתר (הדרך המומלצת)","steps":[{"text":"הלקוח נכנס לדף הפעלת SIM/eSIM באתר wecom ובוחר \"כרטיס סים\".","img":null},{"text":"מזין את מספר הנייד שמפעילים.","img":null},{"text":"מזין ת״ז או ח.פ מלא כולל ספרת ביקורת – כפי שהוזן בעת ההזמנה.","img":null},{"text":"מזין 4 ספרות אחרונות של אמצעי התשלום (אשראי או חשבון בנק) – כפי שהוזנו בעת ההזמנה.","img":null},{"text":"מזין את מספר הסים המלא.","img":null},{"text":"בוחר מועד ניוד: מיידי, או תאריך ושעה עתידיים.","img":null},{"text":"קוד אימות נשלח למכשיר לצורך אימות הבעלות על הקו – מזינים אותו. לא הגיע? \"לא קיבלתי קוד, שלח שוב\" (ואם עדיין לא – O-54).","img":null},{"text":"מסמנים את ההצהרה (בעל/ת הקו + תנאי הניוד) ולוחצים \"אישור\".","img":null}]},{"title":"אחרי האישור","steps":[{"text":"להכניס את הסים למכשיר ולבצע כיבוי והדלקה.","img":null},{"text":"הפעלת הסים מתחילה את תהליך הניוד, שנמשך עד 30 דקות – רק אם התחיל בשעות הפעילות.","img":null},{"text":"שעות פעילות מערכת ההפעלה והניוד: א׳–ה׳ 08:00–21:00, ו׳ 08:00–13:00. סגור בשבת ובחגים. (⚠ חסר: מה קורה לבקשה שהוגשה מחוץ לשעות – נכנסת לתור אוטומטית ליום העבודה הבא?)","img":null},{"text":"לוודא חיווי רשת ולבצע שיחת ניסיון ו-SMS.","img":null},{"text":"אין גלישה? קודם שליחת הגדרות גלישה מה-CRM (ביצוע פעולות ← גלישה ותוכן ← שליחת הגדרות גלישה), ורק אם לא עזר – הגדרת APN ידנית (נושא \"הגדרת APN במכשיר\").","img":null}]},{"title":"הפעלה בליווי נציג","steps":[{"text":"⚠ חסר: נתיב ההפעלה ב-CRM כשהנציג מבצע את ההפעלה במקום הלקוח, ומתי מותר לנציג לבצע אותה (למשל לקוח מבוגר / ללא גישה לאינטרנט).","img":null}]},{"title":"מה חשוב לומר ללקוח","steps":[{"text":"החיוב על השירותים מתחיל מרגע הפעלת הסים.","img":null},{"text":"הטבות לתקופה קצובה (למשל מחיר מוזל לכמה חודשים) נספרות מיום ביצוע העסקה, גם אם ההפעלה מתבצעת מאוחר יותר.","img":null},{"text":"יש להפעיל את הסים / להשלים ניוד תוך 90 ימים מיום העסקה – אחרת העסקה מבוטלת והמספר מנותק (ראו O-59).","img":null},{"text":"״הסים יופעל ברגע שתאשר את השלב האחרון. אם ביקשת ניוד מיידי – הקו יעבור אלינו תוך עד חצי שעה, ובזמן הזה ייתכן שלא יהיה שירות בקו הקודם.״","img":null}]},{"title":"תיעוד","steps":[{"text":"לתעד ביומן: הפעלה עצמית / בליווי, מועד ניוד שנבחר, תוצאת הבדיקה אחרי ההפעלה.","img":null}]},{"title":"לבדיקת העורך/ת – למחוק לפני פרסום","steps":[{"text":"לאשר שקוד האימות בניוד נשלח למספר המנויד (שעדיין במפעיל הקודם) – משפיע על ההנחיה ללקוח להשאיר את הסים הישן זמין.","img":null}]}]}};
window.dynamicDocs['kbd_o11'] = {"id":"kbd_o11","topic":"O-51 · הפעלת eSIM באמצעות קוד QR","cat":"sim","docType":"pdf","kind":"O","desc":"דרישות מקדימות, התקנת פרופיל ה-eSIM בסריקת QR, הפעלת הקו באתר, וטעויות נפוצות.","tags":["SIM"],"owner":"","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 2 פערים מסומנים ⚠ חסר + 1 הערות לבדיקה","source":"טיוטות פריטי ידע / O-51 הפעלת eSIM באמצעות קוד QR.docx"},"status":"draft","source":{"name":"O-51 הפעלת eSIM באמצעות קוד QR.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/O-51%20%D7%94%D7%A4%D7%A2%D7%9C%D7%AA%20eSIM%20%D7%91%D7%90%D7%9E%D7%A6%D7%A2%D7%95%D7%AA%20%D7%A7%D7%95%D7%93%20QR.docx?web=1"},"body":{"groups":[{"title":"מתי משתמשים במסמך","steps":[{"text":"לקוח הצטרף עם eSIM וקיבל מייל עם קוד QR, ומבקש עזרה בהתקנה ובהפעלה.","img":null},{"text":"QR לא נסרק או לא הגיע – O-54. מעבר בין SIM פיזי ל-eSIM או החלפת מכשיר – O-52.","img":null}]},{"title":"דרישות מקדימות – לבדוק לפני הכל","steps":[{"text":"המכשיר תומך ב-eSIM: אייפון – הגדרות ← סלולרי, מופיע \"הוסף תכנית סלולרית\". אנדרואיד – הגדרות ← חיבורים ← מנהל כרטיסי SIM, מופיע \"הוספת חבילה סלולרית\". רשימת המכשירים הנתמכים באתר (מדריכים ושירות עצמי ← הגדרות eSIM).","img":null},{"text":"המכשיר אינו חסום למפעילים זרים (מכשיר נעול לחברה אחרת לא יקבל את הפרופיל).","img":null},{"text":"חיבור ל-WiFi או לרשת סלולרית בזמן ההתקנה.","img":null},{"text":"ה-QR זמין: נשלח במייל בעת ההצטרפות, יחד עם כל ההנחיות ופרטים להזנה ידנית.","img":null}]},{"title":"אייפון","steps":[{"text":"הגדרות ← סלולרי ← \"הוסף eSIM\" / \"הוסף תכנית סלולרית\".","img":null},{"text":"בחירה ב\"השתמש בקוד QR\" וסריקת הקוד מהמייל.","img":null},{"text":"מתן שם לקו (למשל wecom) ובחירת קו ברירת מחדל לשיחות ולנתונים.","img":null}]},{"title":"אנדרואיד / סמסונג","steps":[{"text":"הגדרות ← חיבורים ← מנהל כרטיסי SIM ← \"הוספת eSIM\" / \"הוספת חבילה סלולרית\".","img":null},{"text":"סריקת קוד ה-QR מהמייל ואישור.","img":null},{"text":"בחירת הקו המועדף לשיחות, להודעות ולנתונים.","img":null},{"text":"את ה-QR סורקים ממסך אחר (מחשב / מכשיר נוסף) או מדף מודפס. אי אפשר לסרוק במצלמה קוד שמוצג על אותו מסך. אין מסך נוסף? להשתמש בהזנה הידנית לפי הפרטים במייל.","img":null}]},{"title":"שלב 2 – הפעלת הקו באתר","steps":[{"text":"את הפעלת הקו מבצעים רק אחרי שהתקנת פרופיל ה-eSIM במכשיר הסתיימה.","img":null},{"text":"דף הפעלת SIM/eSIM באתר ← בחירה ב-eSIM.","img":null},{"text":"הזנת מספר הנייד, ת״ז / ח.פ מלא כולל ספרת ביקורת ו-4 ספרות אחרונות של אמצעי התשלום – כפי שהוזנו בהזמנה.","img":null},{"text":"בחירת מועד ניוד (מיידי / עתידי), הזנת קוד האימות, סימון ההצהרה ו\"אישור\" – כמו בהפעלת SIM פיזי (O-50).","img":null},{"text":"ניוד עד 30 דקות בשעות הפעילות (א׳–ה׳ 08:00–21:00, ו׳ 08:00–13:00).","img":null}]},{"title":"טעויות נפוצות","steps":[{"text":"הלקוח מחק את פרופיל ה-eSIM מהמכשיר: לא ניתן לשחזר מהמכשיר – נדרש קוד QR חדש דרך שירות הלקוחות / תמיכה טכנית ‎*5166. (⚠ חסר: נתיב הנפקת QR מחדש ב-CRM והאם יש עלות)","img":null},{"text":"הלקוח הפעיל באתר לפני התקנת הפרופיל: (⚠ חסר: האם צריך לבטל/לרענן את ההפעלה, ומי מטפל)","img":null},{"text":"ההתקנה הסתיימה אבל אין גלישה: לוודא שהקו נבחר לנתונים סלולריים, ואז מסמך O-53.","img":null},{"text":"\"לא ניתן להוסיף eSIM\" / \"הקוד כבר בשימוש\": O-54.","img":null}]},{"title":"תיעוד","steps":[{"text":"לתעד: דגם המכשיר, האם הפרופיל הותקן, האם הקו הופעל באתר, ותוצאה.","img":null}]},{"title":"לבדיקת העורך/ת – למחוק לפני פרסום","steps":[{"text":"לאשר האם קוד QR של wecom הוא חד-פעמי (אחרי סריקה מוצלחת אי אפשר להשתמש בו שוב) – עמוד ה-eSIM באתר לא מציין זאת.","img":null}]}]}};
window.dynamicDocs['kbd_o12'] = {"id":"kbd_o12","topic":"O-52 · מעבר מ-SIM פיזי ל-eSIM או מעבר למכשיר חדש","cat":"sim","docType":"pdf","kind":"O","desc":"מעבר מכרטיס פיזי ל-eSIM ולהפך, והעברת eSIM למכשיר חדש – כולל סדר הפעולות המחייב בהחלפת סים.","tags":["SIM"],"owner":"","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 3 פערים מסומנים ⚠ חסר","source":"טיוטות פריטי ידע / O-52 מעבר מ-SIM פיזי ל-eSIM או מעבר למכשיר חדש.docx"},"status":"draft","source":{"name":"O-52 מעבר מ-SIM פיזי ל-eSIM או מעבר למכשיר חדש.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/O-52%20%D7%9E%D7%A2%D7%91%D7%A8%20%D7%9E-SIM%20%D7%A4%D7%99%D7%96%D7%99%20%D7%9C-eSIM%20%D7%90%D7%95%20%D7%9E%D7%A2%D7%91%D7%A8%20%D7%9C%D7%9E%D7%9B%D7%A9%D7%99%D7%A8%20%D7%97%D7%93%D7%A9.docx?web=1"},"body":{"groups":[{"title":"מתי משתמשים במסמך","steps":[{"text":"לקוח עם SIM פיזי רוצה לעבור ל-eSIM (או להפך).","img":null},{"text":"לקוח עם eSIM עובר למכשיר חדש.","img":null},{"text":"סים אבוד או גנוב – O-55.","img":null}]},{"title":"לפני שמתחילים","steps":[{"text":"החלפת SIM / eSIM = זיהוי מלא + צילום ת״ז בהתאם לתהליך. לא הושלם הזיהוי הנדרש = לא מוסרים מידע ולא מבצעים פעולה.","img":null},{"text":"כשנדרש צילום ת״ז – להנחות את הלקוח להשחיר מראש כל פרט שאינו נדרש. גלויים נשארים רק: שם כפי שמופיע בתעודה ומספר ת״ז.","img":null},{"text":"במעבר ל-eSIM: לבדוק שהמכשיר תומך ב-eSIM ואינו חסום למפעילים זרים (ראו O-51).","img":null}]},{"title":"סדר הפעולות המחייב בהחלפת סים","steps":[{"text":"לפני שליחת סים חדש והפעלתו, חובה:","img":null},{"text":"לחסום את הסים הקודם.","img":null},{"text":"לבדוק את סטטוס המנוי.","img":null},{"text":"רק לאחר השלמת הבדיקות – לשלוח ולהפעיל את הסים החדש.","img":null},{"text":"אין לדלג על שלבים או לשנות את סדר הפעולות.","img":null}]},{"title":"SIM פיזי ← eSIM","steps":[{"text":"זיהוי מלא + צילום ת״ז.","img":null},{"text":"בדיקת תמיכת המכשיר ב-eSIM.","img":null},{"text":"חסימת הסים הפיזי הקודם ובדיקת סטטוס המנוי (סדר הפעולות למעלה).","img":null},{"text":"הנפקת QR ללקוח. (⚠ חסר: נתיב הנפקת ה-QR ב-CRM ולאיזה מייל הוא נשלח)","img":null},{"text":"הלקוח מתקין את הפרופיל ומפעיל לפי O-51, ומוציא את הסים הפיזי רק אחרי שה-eSIM עובד.","img":null}]},{"title":"eSIM ← SIM פיזי","steps":[{"text":"זיהוי מלא + צילום ת״ז.","img":null},{"text":"הזמנת כרטיס פיזי: משלוח (O-56) או איסוף (O-57).","img":null},{"text":"חסימת ה-eSIM, בדיקת סטטוס המנוי, ורק אז הפעלת הכרטיס החדש. (⚠ חסר: האם חוסמים את ה-eSIM כבר בעת ההזמנה (ואז הלקוח בלי שירות עד שהכרטיס מגיע) או רק ביום ההפעלה)","img":null},{"text":"אחרי שהכרטיס הפיזי עובד – למחוק את פרופיל ה-eSIM מהמכשיר.","img":null}]},{"title":"eSIM למכשיר חדש","steps":[{"text":"קודם מוחקים את פרופיל ה-eSIM מהמכשיר הישן.","img":null},{"text":"רק אחר כך סורקים במכשיר החדש את קוד ה-QR שהתקבל במייל. (⚠ חסר: האם ה-QR המקורי עדיין תקף או שנדרש QR חדש)","img":null},{"text":"מכשיר ישן אבד / תקול ולא ניתן למחוק? פונים ל-‎*5166 להנפקת QR חדש.","img":null}]},{"title":"תיעוד","steps":[{"text":"לתעד: כיוון המעבר, אישור הזיהוי וצילום הת״ז, מועד חסימת הסים הקודם, מועד הפעלת החדש.","img":null}]}]}};
window.dynamicDocs['kbd_r10'] = {"id":"kbd_r10","topic":"O-53 · תקלה לאחר הפעלת SIM/eSIM - אין קליטה או אין גלישה","cat":"sim","docType":"pdf","kind":"O","desc":"אבחון וטיפול בקו חדש שהופעל אבל אין בו שירות, שיחות, גלישה או SMS.","tags":["SIM"],"owner":"שחר","stages":[],"track":{"state":"קיים חלקית","priority":"","gap":"טיוטת Word לבדיקה: 3 פערים מסומנים ⚠ חסר + 1 הערות לבדיקה","source":"טיוטות פריטי ידע / O-53 תקלה לאחר הפעלת SIM-eSIM - אין קליטה או אין גלישה.docx"},"status":"draft","source":{"name":"O-53 תקלה לאחר הפעלת SIM-eSIM - אין קליטה או אין גלישה.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/O-53%20%D7%AA%D7%A7%D7%9C%D7%94%20%D7%9C%D7%90%D7%97%D7%A8%20%D7%94%D7%A4%D7%A2%D7%9C%D7%AA%20SIM-eSIM%20-%20%D7%90%D7%99%D7%9F%20%D7%A7%D7%9C%D7%99%D7%98%D7%94%20%D7%90%D7%95%20%D7%90%D7%99%D7%9F%20%D7%92%D7%9C%D7%99%D7%A9%D7%94.docx?web=1"},"body":{"groups":[{"title":"מתי משתמשים במסמך","steps":[{"text":"הקו הופעל (SIM או eSIM) ואחד השירותים לא עובד.","img":null}]},{"title":"זיהוי","steps":[{"text":"בירור התקלה ובדיקות כלליות – ללא זיהוי, כל עוד לא מבוצע שינוי בקו או בחשבון.","img":null},{"text":"רענון סים / בדיקת תקינות קו (קוד 13/33, פרופיל) – ללא זיהוי.","img":null},{"text":"ברגע שנדרשת פעולה בקו – לבצע קודם את הזיהוי הנדרש.","img":null}]},{"title":"שלב 1 – תשאול","steps":[{"text":"מה בדיוק לא עובד: אין שירות בכלל / שיחות / גלישה / SMS?","img":null},{"text":"כמה זמן עבר מההפעלה? ניוד נמשך עד 30 דקות, ורק בשעות הפעילות (א׳–ה׳ 08:00–21:00, ו׳ 08:00–13:00).","img":null},{"text":"SIM פיזי או eSIM? דגם המכשיר? מכשיר מיבואן רשמי ונקנה בארץ?","img":null}]},{"title":"שלב 2 – בדיקות במערכת","steps":[{"text":"סטטוס הקו ב-CRM והאם הניוד הושלם. (⚠ חסר: רשימת סטטוסי הקו ב-CRM (פעיל / רשום / בניוד…) ומשמעות כל אחד)","img":null},{"text":"החבילה פעילה ויש יתרת גלישה.","img":null},{"text":"שירות VoLTE קיים ב-CRM.","img":null},{"text":"בדיקת תקינות קו – קוד 13/33 / פרופיל. (⚠ חסר: מה המשמעות של קוד 13 ושל קוד 33 ומה עושים בכל מקרה)","img":null}]},{"title":"שלב 3 – בדיקות במכשיר","steps":[{"text":"מצב טיסה לדקה, או כיבוי והדלקה.","img":null},{"text":"הקו מופעל במכשיר (באייפון: \"הפעל קו זה\"), ובמכשיר עם שני קווים – wecom נבחר לנתונים סלולריים.","img":null},{"text":"נתונים סלולריים פעילים.","img":null},{"text":"SIM פיזי: להוציא ולהכניס את הכרטיס.","img":null}]},{"title":"שלב 4 – אין גלישה","steps":[{"text":"שליחת הגדרות גלישה מה-CRM (ביצוע פעולות ← גלישה ותוכן ← שליחה).","img":null},{"text":"עדיין אין גלישה – הגדרת APN ידנית: הערך \"we\" באותיות קטנות (באייפון בכל 4 שורות ה-APN; באנדרואיד: שם = we, APN = we, לשמור ולבחור).","img":null},{"text":"לא ניתן להגדיר APN במהלך שיחה – להנחות ולחזור ללקוח, או לשלוח הנחיה בכתב.","img":null},{"text":"בחו״ל אין להגדיר APN – לעבור למסלולי החו״ל (M-00).","img":null}]},{"title":"שלב 5 – אין שיחות / שיחות נופלות","steps":[{"text":"בדיקת VoLTE: VoLTE פעיל במכשיר? המכשיר תומך (רשימות הנתמכים)? המכשיר מיבואן רשמי ונקנה בארץ? השירות קיים ב-CRM?","img":null},{"text":"האם במהלך שיחה המכשיר יורד ל-3G? אם כן – רענון: רענון דור 5 + רענון סים, רענון VoLTE, כיבוי והדלקה.","img":null},{"text":"בדיקה חוזרת: עדיין יורד ל-3G – ממשיכים לטופס רדיו. נשאר על 4G/5G – VoLTE תקין.","img":null}]},{"title":"שלב 6 – הסלמה","steps":[{"text":"כל הבדיקות בוצעו ותועדו והתקלה נמשכת – הסלמה. (⚠ חסר: לאן מסלימים תקלת קו חדש בארץ (מומחה / תמיכה טכנית דרג ב׳), ובאיזה פורמט)","img":null},{"text":"אין לפתוח פנייה ל-IT.","img":null},{"text":"זוהתה תקלה רוחבית (כמה לקוחות חדשים עם אותה תקלה)? להציף לאחמ״ש.","img":null}]},{"title":"תיעוד","steps":[{"text":"לתעד כל בדיקה ותוצאה (כולל שליחת הגדרות ורענונים) – בלי תיעוד, ההסלמה תחזור לנציג.","img":null}]},{"title":"לבדיקת העורך/ת – למחוק לפני פרסום","steps":[{"text":"ממפת המסמכים: שחר שלחה לבדוק","img":null}]}]}};
window.dynamicDocs['kbd_r11'] = {"id":"kbd_r11","topic":"O-54 · קוד QR לא נסרק או קוד אימות לא התקבל","cat":"sim","docType":"pdf","kind":"O","desc":"טיפול כשמייל ה-QR לא הגיע, כשהקוד לא נסרק או נכשל, וכשקוד האימות בהפעלה לא מגיע.","tags":["SIM"],"owner":"","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 4 פערים מסומנים ⚠ חסר","source":"טיוטות פריטי ידע / O-54 קוד QR לא נסרק או קוד אימות לא התקבל.docx"},"status":"draft","source":{"name":"O-54 קוד QR לא נסרק או קוד אימות לא התקבל.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/O-54%20%D7%A7%D7%95%D7%93%20QR%20%D7%9C%D7%90%20%D7%A0%D7%A1%D7%A8%D7%A7%20%D7%90%D7%95%20%D7%A7%D7%95%D7%93%20%D7%90%D7%99%D7%9E%D7%95%D7%AA%20%D7%9C%D7%90%20%D7%94%D7%AA%D7%A7%D7%91%D7%9C.docx?web=1"},"body":{"groups":[{"title":"שלב 1 – מה בדיוק הבעיה","steps":[{"text":"מייל עם קוד ה-QR לא הגיע ← שלב 2.","img":null},{"text":"ה-QR לא נסרק ← שלב 3.","img":null},{"text":"הסריקה מצליחה אבל מתקבלת שגיאה ← שלב 4.","img":null},{"text":"קוד האימות בדף ההפעלה לא מגיע ← שלב 5.","img":null}]},{"title":"שלב 2 – המייל לא הגיע","steps":[{"text":"לבקש מהלקוח לבדוק בתיקיות ספאם / קידומי מכירות.","img":null},{"text":"לוודא שכתובת המייל במערכת נכונה (עדכון פרטים – I-111, בזיהוי מלא).","img":null},{"text":"שליחה חוזרת של המייל. (⚠ חסר: איך שולחים מחדש את מייל ה-QR מה-CRM, ואם אפשר לשלוח לכתובת אחרת)","img":null}]},{"title":"שלב 3 – ה-QR לא נסרק","steps":[{"text":"סורקים מתוך הגדרות המכשיר (הוספת eSIM), לא מאפליקציית המצלמה הרגילה.","img":null},{"text":"ה-QR מוצג על מסך אחר או מודפס – לא על מסך המכשיר שמתקין.","img":null},{"text":"בהירות מסך מלאה, עדשה נקייה, הקוד שלם בתוך המסגרת.","img":null},{"text":"המכשיר מחובר ל-WiFi או לרשת סלולרית.","img":null},{"text":"עדיין לא נסרק – הזנה ידנית לפי הפרטים שבמייל.","img":null}]},{"title":"שלב 4 – שגיאה אחרי הסריקה","steps":[{"text":"לבדוק שהמכשיר תומך ב-eSIM ואינו חסום למפעילים זרים.","img":null},{"text":"לבדוק בהגדרות אם פרופיל wecom כבר מותקן – ייתכן שהקוד כבר נסרק בהצלחה.","img":null},{"text":"הפרופיל נמחק או שהקוד נוצל – נדרש QR חדש דרך ‎*5166 (בזיהוי מלא). (⚠ חסר: האם QR של wecom חד-פעמי, ונתיב ההנפקה מחדש)","img":null}]},{"title":"שלב 5 – קוד האימות בהפעלה לא מגיע","steps":[{"text":"ללחוץ \"לא קיבלתי קוד, שלח שוב\".","img":null},{"text":"לבדוק לאיזה מכשיר הקוד אמור להגיע. (⚠ חסר: בניוד – האם הקוד נשלח למספר המנויד שעדיין פעיל אצל המפעיל הקודם (ואז הסים הישן חייב להיות במכשיר))","img":null},{"text":"לבדוק שאין חסימת קבלת SMS על הקו.","img":null},{"text":"עדיין לא מגיע – (⚠ חסר: חלופה להפעלה (הפעלה ע״י נציג?))","img":null}]},{"title":"הסלמה ותיעוד","steps":[{"text":"לתעד: דגם, איזה שלב נכשל, הודעת השגיאה המדויקת, האם נשלח QR חדש.","img":null},{"text":"אין לפתוח פנייה ל-IT.","img":null}]}]}};
window.dynamicDocs['kbd_r12'] = {"id":"kbd_r12","topic":"O-55 · החלפת SIM אבוד, גנוב או תקול וחסימת קו","cat":"sim","docType":"pdf","kind":"O","desc":"חסימה מיידית של קו ומכשיר שאבדו או נגנבו, והנפקת סים חלופי לפי סדר הפעולות המחייב.","tags":["SIM"],"owner":"שחר","stages":[],"track":{"state":"קיים חלקית","priority":"","gap":"טיוטת Word לבדיקה: 4 פערים מסומנים ⚠ חסר + 1 הערות לבדיקה","source":"טיוטות פריטי ידע / O-55 החלפת SIM אבוד, גנוב או תקול וחסימת קו.docx"},"status":"draft","source":{"name":"O-55 החלפת SIM אבוד, גנוב או תקול וחסימת קו.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/O-55%20%D7%94%D7%97%D7%9C%D7%A4%D7%AA%20SIM%20%D7%90%D7%91%D7%95%D7%93%2C%20%D7%92%D7%A0%D7%95%D7%91%20%D7%90%D7%95%20%D7%AA%D7%A7%D7%95%D7%9C%20%D7%95%D7%97%D7%A1%D7%99%D7%9E%D7%AA%20%D7%A7%D7%95.docx?web=1"},"body":{"groups":[{"title":"מתי משתמשים במסמך","steps":[{"text":"לקוח מדווח שהמכשיר או הסים אבדו או נגנבו.","img":null},{"text":"פנייה כזו מתקבלת 24/7 כל השנה, למעט יום כיפור.","img":null}]},{"title":"שלב 1 – חסימה מיידית (קודם כול)","steps":[{"text":"אובדן מכשיר – חסימת שיחות יוצאות / SMS יוצא = זיהוי חלקי (פעולה למניעת נזק מיידי).","img":null},{"text":"הלקוח יכול גם לחסום בעצמו בכל עת: באזור האישי, או בטופס חסימת SIM באתר (מספר ת״ז כולל ספרת ביקורת, 4 ספרות אחרונות של אמצעי התשלום, מספר הטלפון).","img":null},{"text":"(⚠ חסר: אילו חסימות הנציג מבצע ב-CRM ובאיזה נתיב – יוצאות בלבד / חסימת קו מלאה)","img":null}]},{"title":"שלב 2 – חסימת המכשיר (IMEI)","steps":[{"text":"ניתן לחסום את המכשיר עצמו רק אם ה-IMEI שלו עודכן אצלנו מראש ושויך לקו.","img":null},{"text":"סטטוס IMEI ניתן לבדוק באתר (עמוד \"מידע על אובדן או גניבה\").","img":null},{"text":"(⚠ חסר: האם נדרש אישור משטרה לחסימת IMEI)","img":null}]},{"title":"שלב 3 – הנפקת סים חלופי","steps":[{"text":"החלפת SIM/eSIM = זיהוי מלא + צילום ת״ז. לא הושלם הזיהוי הנדרש = לא מוסרים מידע ולא מבצעים פעולה.","img":null},{"text":"כשנדרש צילום ת״ז – להנחות את הלקוח להשחיר מראש כל פרט שאינו נדרש. גלויים נשארים רק: שם כפי שמופיע בתעודה ומספר ת״ז.","img":null},{"text":"סדר הפעולות המחייב:","img":null},{"text":"לחסום את הסים הקודם.","img":null},{"text":"לבדוק את סטטוס המנוי.","img":null},{"text":"רק לאחר השלמת הבדיקות – לשלוח ולהפעיל את הסים החדש.","img":null},{"text":"eSIM: הנפקת QR חדש (O-51). SIM פיזי: משלוח (O-56) או איסוף (O-57).","img":null},{"text":"(⚠ חסר: עלות סים חלופי ודמי משלוח, אם יש)","img":null}]},{"title":"מה לומר ללקוח","steps":[{"text":"לחסום מיד – החברה אינה אחראית לשימוש בלתי מורשה בסים או במכשיר שאבדו, אלא ברשלנות חמורה שלה. (⚠ חסר: ניסוח מאושר לגבי חיובים על שימוש שבוצע לפני החסימה)","img":null},{"text":"מומלץ לחסום גם חשבונות שמחוברים למספר (WhatsApp, בנקים) ולשנות סיסמאות.","img":null},{"text":"״אני חוסמת עכשיו את השיחות וההודעות היוצאות כדי שאף אחד לא ישתמש בקו. אחרי שנשלים זיהוי מלא, אנפיק לך סים חדש על אותו מספר.״","img":null}]},{"title":"תיעוד","steps":[{"text":"לתעד: שעת הדיווח, אילו חסימות בוצעו, האם נחסם IMEI, רמת הזיהוי, ואיך יימסר הסים החדש.","img":null}]},{"title":"לבדיקת העורך/ת – למחוק לפני פרסום","steps":[{"text":"ממפת המסמכים: שחר שלחה לבדוק","img":null}]}]}};
window.dynamicDocs['kbd_o13'] = {"id":"kbd_o13","topic":"O-56 · בירור סטטוס משלוח SIM","cat":"sim","docType":"pdf","kind":"O","desc":"בדיקת סטטוס הזמנה ומשלוח של כרטיס SIM, ומה עושים כשהמשלוח מתעכב.","tags":["SIM"],"owner":"שחר","stages":[],"track":{"state":"קיים חלקית","priority":"","gap":"טיוטת Word לבדיקה: 5 פערים מסומנים ⚠ חסר + 2 הערות לבדיקה","source":"טיוטות פריטי ידע / O-56 בירור סטטוס משלוח SIM.docx"},"status":"draft","source":{"name":"O-56 בירור סטטוס משלוח SIM.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/O-56%20%D7%91%D7%99%D7%A8%D7%95%D7%A8%20%D7%A1%D7%98%D7%98%D7%95%D7%A1%20%D7%9E%D7%A9%D7%9C%D7%95%D7%97%20SIM.docx?web=1"},"body":{"groups":[{"title":"לפני שמתחילים","steps":[{"text":"מסירת פרטים על החשבון = זיהוי מלא. אין למסור מידע לפני השלמת הזיהוי.","img":null}]},{"title":"בדיקת הסטטוס","steps":[{"text":"לאתר את ההזמנה ב-CRM. (⚠ חסר: היכן מוצג סטטוס ההזמנה/המשלוח ב-CRM)","img":null},{"text":"לבדוק את כתובת המשלוח שנמסרה.","img":null},{"text":"לבדוק את סטטוס השליח ומספר המעקב. (⚠ חסר: חברת השילוח, מספר מעקב, האם ללקוח נשלח SMS עם קישור למעקב)","img":null},{"text":"לבדוק את זמן האספקה הצפוי. (⚠ חסר: זמן אספקה מוצהר (ימי עסקים) ומתי משלוח נחשב מתעכב)","img":null}]},{"title":"המשלוח מתעכב","steps":[{"text":"אם המכשיר תומך – להציע חיבור מיידי ב-eSIM במקום להמתין (O-51).","img":null},{"text":"שינוי כתובת אחרי שליחה. (⚠ חסר: האם אפשרי, ואיך)","img":null},{"text":"משלוח שאבד – הנפקת כרטיס חדש. (⚠ חסר: מי מאשר, והאם יש לחסום את הכרטיס שבדרך לפני ההנפקה)","img":null},{"text":"אפשרות איסוף עצמי – O-57.","img":null}]},{"title":"חשוב לזכור","steps":[{"text":"יש להפעיל את הסים תוך 90 ימים מיום העסקה, אחרת העסקה מבוטלת והמספר מנותק – משלוח שמתעכב מאוד מקרב את המועד (O-59).","img":null}]},{"title":"תיעוד","steps":[{"text":"לתעד: סטטוס שנמצא, מה נמסר ללקוח, ופעולה שבוצעה (eSIM / שליחה חוזרת / איסוף).","img":null}]},{"title":"לבדיקת העורך/ת – למחוק לפני פרסום","steps":[{"text":"במקורות הציבוריים והפנימיים שנבדקו אין מידע על תהליך המשלוח – רוב המסמך דורש השלמה.","img":null},{"text":"ממפת המסמכים: שחר שלחה לבדוק / לפתוח לשירות","img":null}]}]}};
window.dynamicDocs['kbd_i10'] = {"id":"kbd_i10","topic":"O-57 · איסוף SIM מנקודת שירות / Home Center","cat":"sim","docType":"pdf","kind":"O","desc":"מידע לנציג על איסוף כרטיס SIM בסניפי הום סנטר: תנאים, מה מביאים, ומה עושים אחרי האיסוף.","tags":["SIM"],"owner":"","stages":[],"track":{"state":"קיים","priority":"","gap":"טיוטת Word לבדיקה: 7 פערים מסומנים ⚠ חסר + 2 הערות לבדיקה","source":"טיוטות פריטי ידע / O-57 איסוף SIM מנקודת שירות - Home Center.docx"},"status":"draft","source":{"name":"O-57 איסוף SIM מנקודת שירות - Home Center.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/O-57%20%D7%90%D7%99%D7%A1%D7%95%D7%A3%20SIM%20%D7%9E%D7%A0%D7%A7%D7%95%D7%93%D7%AA%20%D7%A9%D7%99%D7%A8%D7%95%D7%AA%20-%20Home%20Center.docx?web=1"},"body":{"groups":[{"title":"על השירות","steps":[{"text":"לקוחות יכולים לאסוף כרטיס SIM בסניפי הום סנטר במקום לקבל אותו במשלוח. (⚠ חסר: האם זה שיתוף פעולה פעיל, ובאילו סניפים)","img":null}]},{"title":"תנאי האיסוף","steps":[{"text":"סניפים ושעות: (⚠ חסר: רשימת סניפים או קישור, ושעות פתיחה)","img":null},{"text":"מה הלקוח מביא: (⚠ חסר: תעודה מזהה? הודעת SMS / קוד איסוף?)","img":null},{"text":"איסוף ע״י אדם אחר: (⚠ חסר: מותר? באילו תנאים?)","img":null},{"text":"זמן המתנה לאיסוף: (⚠ חסר: כמה ימים הכרטיס ממתין בסניף, ומה קורה אחר כך)","img":null},{"text":"עלות: (⚠ חסר: האם יש עלות לאיסוף) (באתר: \"ללא עלות סים\" בכל החבילות)","img":null}]},{"title":"אחרי האיסוף","steps":[{"text":"הפעלה עצמית באתר לפי O-50.","img":null},{"text":"יש להפעיל תוך 90 ימים מיום העסקה (O-59).","img":null}]},{"title":"בעיות נפוצות","steps":[{"text":"הכרטיס לא נמצא בסניף. (⚠ חסר: למי פונים ומה בודקים)","img":null},{"text":"הלקוח רוצה לעבור למשלוח לבית – O-56.","img":null}]},{"title":"לבדיקת העורך/ת – למחוק לפני פרסום","steps":[{"text":"לא נמצא מידע ציבורי או פנימי על איסוף מהום סנטר. המסמך הוא שלד בלבד וצריך להיכתב ע״י בעל/ת התהליך.","img":null},{"text":"ממפת המסמכים: במפה: קיים – להשוות לגרסה הקיימת במנהלת","img":null}]}]}};
window.dynamicDocs['kbd_r13'] = {"id":"kbd_r13","topic":"O-59 · טיפול בקווים שנרכשו אך לא הופעלו","cat":"sim","docType":"pdf","kind":"O","desc":"טיפול בלקוח שרכש קו ועוד לא הפעיל אותו: חלון 90 הימים, הסיבות הנפוצות, והדרכה להפעלה.","tags":["SIM"],"owner":"","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 0 פערים מסומנים ⚠ חסר + 1 הערות לבדיקה","source":"טיוטות פריטי ידע / O-59 טיפול בקווים שנרכשו אך לא הופעלו.docx"},"status":"draft","source":{"name":"O-59 טיפול בקווים שנרכשו אך לא הופעלו.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/O-59%20%D7%98%D7%99%D7%A4%D7%95%D7%9C%20%D7%91%D7%A7%D7%95%D7%95%D7%99%D7%9D%20%D7%A9%D7%A0%D7%A8%D7%9B%D7%A9%D7%95%20%D7%90%D7%9A%20%D7%9C%D7%90%20%D7%94%D7%95%D7%A4%D7%A2%D7%9C%D7%95.docx?web=1"},"body":{"groups":[{"title":"הכלל החשוב","steps":[{"text":"הפעלת הסים, השלמת הניוד או שימוש במנוי תוך 90 ימים ממועד העסקה הם תנאי מהותי. אחרי 90 ימים בלי הפעלה – העסקה מבוטלת והמספר מנותק.","img":null},{"text":"אחרי הביטול הלקוח יכול להצטרף מחדש לתוכניות שתקפות באותו מועד. אין התחייבות שהמספר יהיה עדיין פנוי, או שהתנאים יהיו דומים.","img":null},{"text":"החיוב מתחיל מרגע ההפעלה, אבל הטבות לתקופה קצובה נספרות מיום העסקה.","img":null}]},{"title":"שלב 1 – בדיקה","steps":[{"text":"זיהוי מלא.","img":null},{"text":"מועד העסקה וכמה ימים נשארו עד תום 90 הימים.","img":null},{"text":"סוג הקו (SIM / eSIM) והאם ביקש ניוד.","img":null}]},{"title":"שלב 2 – למה לא הופעל","steps":[{"text":"הכרטיס לא הגיע: O-56 (משלוח) / O-57 (איסוף). מכשיר תומך – להציע eSIM מיידי.","img":null},{"text":"eSIM – QR לא נסרק / לא הגיע: O-54","img":null},{"text":"לא יודע איך מפעילים: הדרכה לפי O-50 / O-51","img":null},{"text":"ממתין לניוד במועד מאוחר: לוודא שהמועד בתוך 90 הימים","img":null},{"text":"התחרט / לא מעוניין: ביטול עסקה – I-102 (כולל זכות ביטול 14 יום לפי חוק הגנת הצרכן)","img":null}]},{"title":"שלב 3 – סגירת הטיפול","steps":[{"text":"להפעיל יחד עם הלקוח בשיחה כשאפשר, ולוודא שירות.","img":null},{"text":"לא הופעל בשיחה – לתאם חזרה לפני תום 90 הימים (O-156).","img":null}]},{"title":"תיעוד","steps":[{"text":"לתעד: מועד העסקה, הסיבה, מה בוצע, ומועד מעקב אם נקבע.","img":null}]},{"title":"לבדיקת העורך/ת – למחוק לפני פרסום","steps":[{"text":"לאשר האם הלקוח מקבל תזכורת לפני תום 90 הימים, והאם יש חיוב כלשהו לפני ההפעלה.","img":null}]}]}};
window.dynamicDocs['kbd_r14'] = {"id":"kbd_r14","topic":"R-36 · Hotspot לא עובד","cat":"tech","docType":"pdf","kind":"R","desc":"אבחון נקודה חמה (Hotspot) שלא עובדת: הפעלה, הגדרת APN שמאפשרת שיתוף, ומגבלות מכשיר.","tags":["טכני"],"owner":"","stages":[{"num":"1","title":"רקע קצר","items":[{"text":"Hotspot (נקודה חמה) הופך את הטלפון למקור אינטרנט אלחוטי למכשירים אחרים. הגלישה מתבצעת על חשבון חבילת הגלישה של הטלפון.","img":null},{"text":"למה APN משפיע דווקא על ה-Hotspot? ה-APN קובע איך המכשיר מתחבר, לאיזה שרתים הוא פונה ואילו שירותים מותרים. האייפון יכול לגלוש, ובכל זאת לא לקבל \"אישור\" לשתף את האינטרנט החוצה – כמו שני שערים נפרדים, כשהמכשיר לא מצליח לפתוח את השער הקטן.","img":null}],"images":[]},{"num":"2","title":"זיהוי","items":[{"text":"הגדרות APN / Hotspot במכשיר – ללא זיהוי.","img":null}],"images":[]},{"num":"3","title":"שלב 1 – תשאול","items":[{"text":"הטלפון עצמו גולש? (לא – מסלול \"אין גלישה סלולרית\").","img":null},{"text":"המכשיר השני לא רואה את הרשת, או מתחבר בלי אינטרנט?","img":null},{"text":"יש יתרת גלישה בחבילה? (⚠ חסר: האם כל החבילות מאפשרות Hotspot, כולל SIM DATA, ואם יש מגבלת נפח לשיתוף)","img":null},{"text":"הלקוח בחו״ל? – בחו״ל אין להגדיר APN (מסלולי החו״ל).","img":null}],"images":[]},{"num":"4","title":"שלב 2 – הפעלת הנקודה החמה","items":[{"text":"אייפון: הגדרות ← סלולרי ← נקודת גישה אישית ← להפעיל \"אפשר לאחרים להצטרף\". בדרך כלל אפשר גם מהווילון העליון במסך הבית.","img":null},{"text":"אנדרואיד/סמסונג: הגדרות ← חיבורים ← נקודה חמה ושיתוף אינטרנט ← נקודה חמה ניידת.","img":null}],"images":[]},{"num":"5","title":"שלב 3 – הגדרות APN","items":[{"text":"קודם שליחת הודעת תצורה אוטומטית (הגדרות גלישה) מה-CRM: ביצוע פעולות ← גלישה ותוכן ← שליחת הגדרות גלישה.","img":null},{"text":"לא עזר – הגדרה ידנית (לא ניתן להגדיר APN במהלך שיחה).","img":null},{"text":"אייפון: הגדרות ← סלולרי ← הסים הראשי ← רשת נתונים סלולריים ← לרשום \"we\" באותיות קטנות בכל 4 שורות ה-APN, כולל השורה תחת \"נקודת גישה אישית\".","img":null},{"text":"אנדרואיד: הגדרות ← חיבורים ← רשתות סלולריות ← שמות נקודות גישה ← \"+\" ← שם: we, APN: we ← שלוש נקודות ← שמור ← לבחור את we (עיגול מסומן).","img":null},{"text":"Google Pixel: הגדרות ← רשת ואינטרנט ← כרטיסי SIM ← הסים של wecom ← שמות נקודות גישה ← \"+\" ← שם: we, APN: we ← שמור.","img":null},{"text":"Xiaomi כשר: אין אפשרות להוסיף נקודות גישה = המכשיר חסום (דגם כשר). אין פתרון מצד wecom.","img":null}],"images":[]},{"num":"6","title":"שלב 4 – בדיקה חוזרת","items":[{"text":"כיבוי והדלקה של הטלפון, ולנסות לחבר מכשיר אחר (כדי לשלול תקלה במכשיר המתחבר).","img":null}],"images":[]},{"num":"7","title":"הסלמה ותיעוד","items":[{"text":"לתעד: דגם, האם נשלחו הגדרות, האם הוגדר APN ידנית ובאילו שורות, תוצאה.","img":null},{"text":"בוצע הכול והתקלה נמשכת – (⚠ חסר: לאן מסלימים). אין לפתוח פנייה ל-IT.","img":null}],"images":[]},{"num":"8","title":"לידיעה","items":[{"text":"שיתוף אינטרנט עלול לחשוף מידע פרטי למשתמשים שמתחברים, ולאפשר להם להיות מזוהים באמצעות המכשיר כבעל הקו. כדאי לשמור על סיסמה חזקה לנקודה החמה.","img":null}],"images":[]},{"num":"9","title":"לבדיקת העורך/ת – למחוק לפני פרסום","items":[{"text":"הקוד R-36 מוצע – לא במפה. קשור ל-O-32 הגדרת APN במכשיר (שחר)","img":null}],"images":[]}],"track":{"state":"קיים חלקית","priority":"","gap":"טיוטת Word לבדיקה: 2 פערים מסומנים ⚠ חסר + 1 הערות לבדיקה","source":"טיוטות פריטי ידע / R-36 Hotspot לא עובד.docx"},"status":"draft","source":{"name":"R-36 Hotspot לא עובד.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/R-36%20Hotspot%20%D7%9C%D7%90%20%D7%A2%D7%95%D7%91%D7%93.docx?web=1"}};
window.dynamicDocs['kbd_r15'] = {"id":"kbd_r15","topic":"R-80 · בירור חיוב גבוה / לא מזוהה","cat":"billing","docType":"pdf","kind":"R","desc":"פירוק חיוב גבוה או לא מזוהה לגורמיו, השוואה לחודשים קודמים, ומה עושים כשהחיוב שגוי.","tags":["חיוב"],"owner":"","stages":[{"num":"1","title":"זיהוי","items":[{"text":"פירוט שימושים ומסירת פרטים על החשבון = זיהוי מלא. אין למסור מידע לפני השלמת הזיהוי.","img":null}],"images":[]},{"num":"2","title":"שלב 1 – תחקור במערכות","items":[{"text":"לא מסתפקים במה שהלקוח מספר – בודקים במערכות.","img":null},{"text":"טוען שהתעריף עלה? נכנסים לחשבוניות, בודקים מתי חל השינוי ומאתרים את הסיבה.","img":null},{"text":"מלין על תעריפי חו״ל? בודקים בשורת \"שיחות\" ב-CRM אם נשלחה אליו הודעה עם קישור לתעריפים.","img":null},{"text":"טוען שלא עודכן? בודקים את היסטוריית ההודעות שנשלחו אליו.","img":null},{"text":"להשוות את החשבונית לחודשים הקודמים ולאתר את הסעיף שגדל.","img":null}],"images":[]},{"num":"3","title":"שלב 2 – סיבות נפוצות","items":[{"text":"עליית מחיר החבילה: ייתכן ניתוב מחיר – הלקוח קיבל SMS מראש. מציעים חלופה לפי I-101.","img":null},{"text":"חיובי חו״ל: I-83. חיובי נדידה עשויים להופיע בחשבונית מאוחרת מזו של חודש השימוש, והם ללא מע״מ.","img":null},{"text":"שיחות לחו״ל מהארץ (מב״ל): מב״ל ≠ שיחות בחו״ל. שיחה מהארץ למספר בחו״ל מחויבת לפי המפעיל הבינלאומי והיעד (או בתוסף מב״ל, 14.9 ₪ לחודש).","img":null},{"text":"שירותי פרמיום / תוכן / צד שלישי: אינם כלולים בתוכנית ומחויבים בנוסף. ניתן לבקש חסימה (החסימה הראשונה ללא תשלום).","img":null},{"text":"חיוב חלקי בחודש הצטרפות / מעבר תוכנית: תשלום קבוע יחסי לפי ימי השירות או לפי היקף השימוש – הגבוה מבין השניים.","img":null},{"text":"הודעות SMS ארוכות: הודעה ארוכה נשלחת כמה הודעות משורשרות (או MMS) ומחויבת בהתאם.","img":null},{"text":"הוצאות גבייה: חוב שלא שולם תוך 14 יום מהמועד מחויב בהוצאות גבייה (I-93).","img":null}],"images":[]},{"num":"4","title":"שלב 3 – כשהחיוב שגוי או שנוי במחלוקת","items":[{"text":"לקוח חויב על שיחות בחו״ל, לא קיבל SMS בנושא, ובאזור האישי הנדידה בחו״ל סגורה – חובה לפתוח שיחת מנהל, אחרי בדיקת הנתונים במערכות.","img":null},{"text":"לקוח חויב על שיחות בחו״ל אחרי שביקש חסימה – להעביר לשיחת מנהל, ולא לציין שמדובר בתקלה.","img":null},{"text":"הלקוח רשאי למסור השגות על חשבון בכתב, תוך 40 יום מהיום שבו נשלח המסמך.","img":null},{"text":"זיכוי – לפי I-82.","img":null},{"text":"הלקוח אינו מרוצה מההכרעה – אפשר להפנות לנציבת התלונות (pniot@we-com.co.il).","img":null}],"images":[]},{"num":"5","title":"תיעוד","items":[{"text":"לתעד: הסעיף שנבדק, מה נמצא בחשבוניות ובשורת \"שיחות\", מה הוסבר, ואם נפתחה שיחת מנהל או זיכוי.","img":null}],"images":[]},{"num":"6","title":"לבדיקת העורך/ת – למחוק לפני פרסום","items":[{"text":"הקוד R-80 מוצע – לא במפה כמסמך נפרד. במפת שירות 360: \"חיוב גבוה/לא מזוהה\" תחת חיובים","img":null}],"images":[]}],"track":{"state":"קיים חלקית","priority":"","gap":"טיוטת Word לבדיקה: 0 פערים מסומנים ⚠ חסר + 1 הערות לבדיקה","source":"טיוטות פריטי ידע / R-80 בירור חיוב גבוה - לא מזוהה.docx"},"status":"draft","source":{"name":"R-80 בירור חיוב גבוה - לא מזוהה.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/R-80%20%D7%91%D7%99%D7%A8%D7%95%D7%A8%20%D7%97%D7%99%D7%95%D7%91%20%D7%92%D7%91%D7%95%D7%94%20-%20%D7%9C%D7%90%20%D7%9E%D7%96%D7%95%D7%94%D7%94.docx?web=1"}};
window.dynamicDocs['kbd_i11'] = {"id":"kbd_i11","topic":"M-80 · הסבר חשבונית","cat":"billing","docType":"pdf","kind":"I","desc":"מבנה מחזור החיוב ומועדי הסליקה, חיובים קבועים מול משתנים, מע״מ, וחיובים שמגיעים בחשבונית מאוחרת.","tags":["חיוב"],"owner":"בת אל","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 2 פערים מסומנים ⚠ חסר + 1 הערות לבדיקה","source":"טיוטות פריטי ידע / M-80 הסבר חשבונית.docx"},"status":"draft","source":{"name":"M-80 הסבר חשבונית.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/M-80%20%D7%94%D7%A1%D7%91%D7%A8%20%D7%97%D7%A9%D7%91%D7%95%D7%A0%D7%99%D7%AA.docx?web=1"},"body":{"html":"<h3>מחזור החיוב ומועדי הסליקה</h3><table><tbody><tr><th>שלב</th><th>תאריך</th><th>מה קורה</th><th>מתי הלקוח מחויב בפועל</th></tr><tr><td>תקופת החיוב</td><td>1–סוף החודש</td><td>צריכת השירותים</td><td>–</td></tr><tr><td>הפקת חשבונית</td><td>1 לחודש הבא</td><td>בילינג, והחשבונית נשלחת ללקוח</td><td>–</td></tr><tr><td>סליקה ראשונה – אשראי</td><td>10 לחודש</td><td>הסליקה מתבצעת ב-wecom</td><td>לפי מחזור החיוב של כרטיס האשראי</td></tr><tr><td>סליקה שנייה – אשראי</td><td>15 לחודש</td><td>ניסיון חוזר</td><td>לפי מחזור החיוב של כרטיס האשראי</td></tr><tr><td>סליקה שלישית – אשראי</td><td>20 לחודש</td><td>ניסיון חוזר</td><td>לפי מחזור החיוב של כרטיס האשראי</td></tr><tr><td>סליקה רביעית – אשראי</td><td>28 לחודש</td><td>ניסיון חוזר</td><td>לפי מחזור החיוב של כרטיס האשראי</td></tr><tr><td>סליקת הוראת קבע בנקאית</td><td>20 לחודש (יום עסקים; שבת/חג – יום העסקים הבא)</td><td>הסליקה מתבצעת ב-wecom</td><td>באותו יום</td></tr></tbody></table><ul><li>מחזור החיוב <b>קלנדרי</b>: מה-1 בחודש עד היום האחרון בו. דוגמה: חשבונית יולי = שירותים שנצרכו ב-1–31/7.</li><li>ב-CRM: סטטוס סליקה באשראי מתעדכן <b>אוטומטית</b> (עבר / לא עבר). סטטוס סליקת הו״ק מתעדכן <b>עד 5 ימי עסקים</b> מיום הסליקה.</li><li>מועד הסליקה אינו בהכרח מועד החיוב בפועל בכרטיס – זה נקבע לפי מחזור החיוב של כרטיס האשראי.</li><li><b>חיובים וזיכויים ברומינג</b> (חבילות גלובל, חבילות weFly, שיחות ו-SMS בחו״ל) – <b>ללא מע״מ</b>.</li><li>עדכון זמני (תדריך 01/10/2026): <b>בחודש הקרוב סליקת הוראות הקבע תהיה ב-12 לחודש.</b> <b>⚠ חסר: לאשר לאיזה חודש זה חל ומתי להסיר מהמסמך</b></li></ul><h3>קבועים מול משתנים</h3><ul><li><b>תשלומים קבועים</b> (דמי מנוי, החבילה) – מחויבים גם אם לא היה שימוש באותו חודש.</li><li><b>חיובים משתנים</b> – שירותים שאינם כלולים בתוכנית: שיחות והודעות לחו״ל, שירותי פרמיום / תוכן / קידומות מיוחדות, שירותי צד שלישי, נדידה.</li><li><b>חודש חלקי</b> (הצטרפות, מעבר תוכנית, ניתוק) – חלק יחסי של התשלום הקבוע לפי ימי השירות או לפי היקף השימוש, הגבוה מבין השניים.</li><li>שיחות נמדדות <b>בשניות</b> (חלק משנייה מעוגל למעלה). בחו״ל ייתכנו יחידות מדידה אחרות.</li></ul><h3>מע״מ</h3><ul><li>לכל החיובים מתווסף מע״מ לפי הדין, <b>למעט</b> שירותי נדידה (חבילות גלובל, weFly, שיחות ו-SMS בחו״ל) – ללא מע״מ.</li></ul><h3>חיובים שמגיעים מאוחר</h3><ul><li>חלק מהחיובים – בעיקר צד שלישי ונדידה – עשויים להופיע <b>בחשבונית מאוחרת</b> מזו של חודש השימוש, כי הרשומות מגיעות ממפעילים זרים.</li><li>אחרי ניתוק: <b>החשבון הסופי נשלח תוך חודשיים</b> ממועד הניתוק.</li></ul><h3>איפה הלקוח רואה את החשבונית</h3><p><b>⚠ חסר: איפה הלקוח רואה ומוריד חשבוניות (אזור אישי / אפליקציה / מייל), ותמונה מסומנת של סעיפי החשבונית.</b></p><h3>השגה על חשבון</h3><ul><li>ניתן למסור השגות <b>בכתב תוך 40 יום</b> מהיום שבו נשלח המסמך. בירור – R-80. זיכוי – I-82.</li></ul><h3>לבדיקת העורך/ת – למחוק לפני פרסום</h3><ul><li>ממפת המסמכים: במפה M-80 הוא מסמך מרכזי; הטיוטה היא מסמך מידע. הערת המפה: להוסיף לינק לעדכון פרטי לקוח</li></ul>"}};
window.dynamicDocs['kbd_r16'] = {"id":"kbd_r16","topic":"I-93 · תשלום חוב","cat":"billing","docType":"pdf","kind":"I","desc":"בדיקת יתרת חוב וסטטוס סליקה, אפשרויות תשלום, ההשלכות של אי-תשלום, והסרת חסימה.","tags":["חיוב"],"owner":"קירה","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 2 פערים מסומנים ⚠ חסר + 1 הערות לבדיקה","source":"טיוטות פריטי ידע / I-93 תשלום חוב.docx"},"status":"draft","source":{"name":"I-93 תשלום חוב.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/I-93%20%D7%AA%D7%A9%D7%9C%D7%95%D7%9D%20%D7%97%D7%95%D7%91.docx?web=1"},"body":{"html":"<h3>זיהוי</h3><ul><li>בעולם השירות כל פעולה מחייבת <b>זיהוי מלא</b>. אם הפונה אינו בעל החשבון – בעל החשבון עולה לשיחה ומאשר את הפעולה.</li><li>לא הושלם הזיהוי הנדרש = לא מוסרים מידע ולא מבצעים פעולה.</li></ul><h3>שלב 1 – מה מצב החוב</h3><ol><li>סטטוס הסליקה ב-CRM: באשראי – מתעדכן אוטומטית (עבר / לא עבר). בהו״ק – עד 5 ימי עסקים מיום הסליקה.</li><li>מועדי הניסיון החוזר באשראי: 10, 15, 20 ו-28 לחודש. סליקה שנכשלה בתחילת החודש עשויה עוד לעבור בניסיון הבא.</li><li>הסכום הפתוח ומאילו חשבוניות הוא מורכב.</li><li>הסיבה לכישלון: כרטיס פג תוקף / הוחלף / חסום? – עדכון אמצעי תשלום (I-81).</li></ol><h3>שלב 2 – אפשרויות תשלום</h3><p><b>⚠ חסר: איך משלמים חוב: תשלום מיידי בשיחה, קישור לתשלום, אזור אישי, ניסיון סליקה חוזר – ומי מורשה לבצע כל אחד.</b></p><p>לא לרשום פרטי כרטיס אשראי בהערות ב-CRM או בצ׳אט.</p><h3>מה קורה כשלא משלמים</h3><ul><li>על תשלום שלא נפרע תוך <b>14 יום</b> מהמועד – <b>הוצאות גבייה</b> לפי גובה החוב והפעולות שנדרשו.</li><li>החברה רשאית <b>לנתק או להגביל</b> את השירות כשחוב לא נפרע, תוך זמן סביר מההודעה ללקוח.</li><li>אי-תשלום <b>בפעם השלישית בתוך 12 חודשים</b> – החברה רשאית לבטל את ההסכם.</li><li>פניות גבייה יכולות להגיע בטלפון, במכתב, במייל או ב-SMS.</li></ul><h3>שלב 3 – הסרת חסימה אחרי תשלום</h3><p><b>⚠ חסר: תוך כמה זמן הקו נפתח אחרי תשלום, האם אוטומטית, ומה עושים אם לא נפתח.</b></p><h3>שיחות גבייה</h3><ul><li>שיחות גבייה הן חלק מפעילות המוקד וחלק מהתפקיד, בדיוק כמו כל שיחה אחרת. אין מקום לוויכוח עם האחמ״ש על קבלתן.</li></ul><h3>תיעוד</h3><ul><li>לתעד: יתרה, סיבת הכישלון, מה בוצע (עדכון אמצעי תשלום / תשלום), והאם הקו נפתח.</li></ul><h3>לבדיקת העורך/ת – למחוק לפני פרסום</h3><ul><li>ממפת המסמכים: כולל גם חסימה עקב חוב (במפה I-95)</li></ul>"}};
window.dynamicDocs['kbd_o14'] = {"id":"kbd_o14","topic":"I-81 · אמצעי תשלום","cat":"billing","docType":"pdf","kind":"I","desc":"עדכון כרטיס אשראי או הוראת קבע: זיהוי, אבטחת פרטי התשלום, ומה קורה עם חוב פתוח.","tags":["חיוב"],"owner":"בת אל","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 3 פערים מסומנים ⚠ חסר + 1 הערות לבדיקה","source":"טיוטות פריטי ידע / I-81 אמצעי תשלום.docx"},"status":"draft","source":{"name":"I-81 אמצעי תשלום.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/I-81%20%D7%90%D7%9E%D7%A6%D7%A2%D7%99%20%D7%AA%D7%A9%D7%9C%D7%95%D7%9D.docx?web=1"},"body":{"html":"<h3>זיהוי</h3><ul><li>עדכון אמצעי תשלום = <b>זיהוי מלא</b>. אם הפונה אינו בעל החשבון – בעל החשבון עולה לשיחה ומאשר.</li></ul><h3>מתי צריך לעדכן</h3><ul><li>כרטיס פג תוקף, הוחלף, בוטל או הוגבל.</li><li>סליקה נכשלה (I-93).</li><li>הלקוח רוצה לעבור מאשראי להוראת קבע, או להפך.</li><li>באחריות הלקוח לוודא שאמצעי התשלום בתוקף ולהודיע על כל שינוי. החברה רשאית לדרוש אמצעי תשלום חלופי כתנאי להמשך השירות.</li></ul><h3>שלבי העדכון</h3><ol><li>זיהוי מלא.</li><li>עדכון הפרטים. <b>⚠ חסר: היכן ואיך – מערכת מאובטחת / IVR / קישור / אזור אישי; האם הנציג רשאי להקליד מספר כרטיס</b></li><li>הוראת קבע בנקאית. <b>⚠ חסר: התהליך (טופס הרשאה לחיוב? אישור בנק?) וזמן הקליטה</b></li><li>יש חוב פתוח? <b>⚠ חסר: האם מבצעים מיד סליקה חוזרת על אמצעי התשלום החדש</b></li><li>לאשר ללקוח שהעדכון נקלט.</li></ol><p><b>אבטחת מידע:</b> לא לרשום מספר כרטיס, תוקף או CVV בהערות, ביומן או בצ׳אט.</p><h3>לידיעה</h3><ul><li>החברה רשאית לגבות חוב מכל אחד מאמצעי התשלום שהלקוח מסר, גם אם ניתן עבור שירות אחר.</li><li>4 הספרות האחרונות של אמצעי התשלום משמשות כפרט זיהוי – אחרי העדכון הן משתנות.</li></ul><h3>תיעוד</h3><ul><li>לתעד: סוג אמצעי התשלום החדש (בלי פרטים), מועד העדכון, והאם בוצעה סליקה חוזרת.</li></ul><h3>לבדיקת העורך/ת – למחוק לפני פרסום</h3><ul><li>ממפת המסמכים: הערת המפה: לינק לפיזבק</li></ul>"}};
window.dynamicDocs['kbd_r17'] = {"id":"kbd_r17","topic":"I-82 · זיכויים והחזרים","cat":"billing","docType":"pdf","kind":"I","desc":"בדיקת זכאות לזיכוי או החזר, מי מאשר, איך זה מופיע ללקוח, והחזרים לפי חוק הגנת הצרכן.","tags":["חיוב"],"owner":"בת אל","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 3 פערים מסומנים ⚠ חסר + 1 הערות לבדיקה","source":"טיוטות פריטי ידע / I-82 זיכויים והחזרים.docx"},"status":"draft","source":{"name":"I-82 זיכויים והחזרים.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/I-82%20%D7%96%D7%99%D7%9B%D7%95%D7%99%D7%99%D7%9D%20%D7%95%D7%94%D7%97%D7%96%D7%A8%D7%99%D7%9D.docx?web=1"},"body":{"html":"<h3>שלב 1 – תחקור לפני כל זיכוי</h3><ul><li><b>לא מסתפקים במה שהלקוח מספר</b> – בודקים במערכות.</li><li>טוען שהתעריף עלה? נכנסים לחשבוניות, בודקים <b>מתי</b> חל השינוי ומאתרים את הסיבה.</li><li>מלין על תעריפי חו״ל? בודקים בשורת <b>\"שיחות\"</b> ב-CRM אם נשלחה אליו הודעה עם קישור לתעריפים.</li><li>טוען שלא עודכן? בודקים את <b>היסטוריית ההודעות</b> שנשלחו אליו.</li></ul><ul><li>לוודא שהחיוב אכן שגוי, או שמדובר במקרה שמזכה לפי הנהלים – ולא להעניק זיכוי כדי \"לסגור\" שיחה.</li></ul><h3>שלב 2 – זכאות וסמכויות</h3><table><tbody><tr><th>מקרה</th><th>מה עושים</th></tr><tr><td>חיוב שגוי שאומת</td><td><b>⚠ חסר: עד איזה סכום הנציג מזכה בעצמו, ומעליו – אחמ״ש / מנהל</b></td></tr><tr><td>חיוב שיחות בחו״ל בלי SMS ועם נדידה סגורה באזור האישי</td><td>שיחת מנהל – חובה</td></tr><tr><td>חיוב בחו״ל אחרי בקשת חסימה</td><td>שיחת מנהל</td></tr><tr><td>ביטול עסקה תוך 14 יום (מכר מרחוק / נקודת מכירה / רוכלות)</td><td>החזר בניכוי התמורה היחסית לשירות שניתן. דמי ביטול: 5% ממחיר העסקה או 100 ₪ – הנמוך מביניהם (לא חלים בביטול בגלל פגם, אי-התאמה או אי-אספקה).</td></tr><tr><td>תקלת רשת ממושכת</td><td><b>⚠ חסר: האם יש מדיניות פיצוי</b></td></tr></tbody></table><h3>שלב 3 – ביצוע והסבר ללקוח</h3><ul><li>זיכוי ברומינג (גלובל, weFly, שיחות ו-SMS בחו״ל) – <b>ללא מע״מ</b>, כמו החיוב המקורי.</li><li><b>⚠ חסר: איך הזיכוי מופיע – בחשבונית הבאה? החזר לכרטיס? תוך כמה זמן</b></li><li>ערובה או פיקדון מוחזרים בתום ההתקשרות – לא לפני חודש מהפסקת השירות והחזרת הסים, ובתנאי שאין חובות.</li></ul><p>״בדקתי את החשבוניות ומצאתי שהחיוב על … לא היה צריך להופיע. אני מזכה אותך ב-… ₪, והזיכוי יופיע ב… .״</p><h3>הסלמה</h3><ul><li>הלקוח חולק על ההחלטה – אחמ״ש. במחלוקת מתמשכת – נציבת התלונות (pniot@we-com.co.il).</li></ul><h3>תיעוד</h3><ul><li>לתעד: מה נבדק, הסיבה לזיכוי, הסכום, מי אישר, ואיך ומתי הוא יופיע.</li></ul><h3>לבדיקת העורך/ת – למחוק לפני פרסום</h3><ul><li>ממפת המסמכים: הערת המפה: איך מתקינים מחוות, פורמט זיכוי</li></ul>"}};
window.dynamicDocs['kbd_o15'] = {"id":"kbd_o15","topic":"O-80 · שליחת חשבונית / אישור תשלום","cat":"billing","docType":"pdf","kind":"O","desc":"שליחת העתק חשבונית, אישור תשלום או חוזה ללקוח – כולל החריג היחיד המותר לפתיחת פנייה ל-IT.","tags":["חיוב"],"owner":"","stages":[],"track":{"state":"קיים חלקית","priority":"","gap":"טיוטת Word לבדיקה: 3 פערים מסומנים ⚠ חסר + 1 הערות לבדיקה","source":"טיוטות פריטי ידע / O-80 שליחת חשבונית - אישור תשלום.docx"},"status":"draft","source":{"name":"O-80 שליחת חשבונית - אישור תשלום.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/O-80%20%D7%A9%D7%9C%D7%99%D7%97%D7%AA%20%D7%97%D7%A9%D7%91%D7%95%D7%A0%D7%99%D7%AA%20-%20%D7%90%D7%99%D7%A9%D7%95%D7%A8%20%D7%AA%D7%A9%D7%9C%D7%95%D7%9D.docx?web=1"},"body":{"groups":[{"title":"זיהוי","steps":[{"text":"מסירת פרטים על החשבון = זיהוי מלא. שולחים רק לכתובת שמעודכנת במערכת. (⚠ חסר: האם מותר לשלוח לכתובת מייל אחרת שהלקוח מוסר בשיחה)","img":null}]},{"title":"לפי סוג המסמך","steps":[{"text":"העתק חשבונית: (⚠ חסר: הנתיב – שליחה מה-CRM / הפניה לאזור האישי או לאפליקציה)","img":null},{"text":"אישור תשלום / יתרה: (⚠ חסר: האם יש מסמך אישור, ואיך מפיקים אותו)","img":null},{"text":"חשבון סופי אחרי ניתוק: נשלח תוך חודשיים ממועד הניתוק.","img":null},{"text":"החוזה שלו: החריג היחיד שבו מותר לפתוח פנייה ל-IT – לצורך הפקת החוזה (עד שמערכות מידע יסדירו את הנושא).","img":null},{"text":"⛔ מעבר לבקשת חוזה – אין לפתוח פניות ל-IT בשום נושא אחר.","img":null}]},{"title":"תיעוד","steps":[{"text":"לתעד: איזה מסמך נשלח, לאן, ובבקשת חוזה – מספר הפנייה ל-IT.","img":null}]},{"title":"לבדיקת העורך/ת – למחוק לפני פרסום","steps":[{"text":"הקוד O-80 מוצע – לא במפה כמסמך נפרד (בגיליון \"טיוטה\": הפקת העתק חשבונית תחת I-80)","img":null}]}]}};
window.dynamicDocs['kbd_r18'] = {"id":"kbd_r18","topic":"I-101 · שינוי מסלול","cat":"plans","docType":"pdf","kind":"I","desc":"מעבר מסלול והוזלה: כללי מעבר, לקוחות עם ניתוב מחיר (טבלת הצעות ותסריטים), ותפעול נכון במערכת.","tags":["מסלולים"],"owner":"ירון","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 2 פערים מסומנים ⚠ חסר + 3 הערות לבדיקה","source":"טיוטות פריטי ידע / I-101 שינוי מסלול.docx"},"status":"draft","source":{"name":"I-101 שינוי מסלול.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/I-101%20%D7%A9%D7%99%D7%A0%D7%95%D7%99%20%D7%9E%D7%A1%D7%9C%D7%95%D7%9C.docx?web=1"},"body":{"html":"<h3>זיהוי</h3><ul><li>שינוי תכנית = <b>זיהוי מלא</b>. לא הושלם הזיהוי הנדרש = לא מוסרים מידע ולא מבצעים פעולה.</li></ul><h3>כללי מעבר מסלול</h3><ul><li>אפשר לעבור לתוכנית אחרת מהתוכניות שמוצעות באותו מועד – <b>לא יותר מפעם אחת בחודש קלנדרי</b>, בתנאי שאין חובות.</li><li>במעבר עלולות להיפסק הטבות של התוכנית הקודמת (חבילות הוזלה, החזרים וכו׳).</li><li><b>אין כפל מבצעים.</b></li><li>תוכנית שהופסקה לא חוזרת – אי אפשר \"להחזיר\" לקוח לחבילה קודמת.</li></ul><h3>תפעול נכון במערכת</h3><p>מנוי במצב <b>\"רשום\"</b>: מחליפים את התכנית <b>מיידית</b> – <b>לא</b> בשדה \"תוכנית הבאה\". שינוי בשדה \"תוכנית הבאה\" במצב רשום הוא טעות: בעת האקטוב המערכת מחזירה את החבילה הקודמת.</p><ul><li>החלפת חבילות <b>שאינן על המדף</b> – באחריות צוות <b>נוק / מרת״מ</b>. <b>⚠ חסר: איך מעבירים אליהם בקשה</b></li></ul><h3>לקוחות עם ניתוב מחיר (עד דצמבר 2026 כולל)</h3><p>לקוחות עם תוכנית שכוללת ניתוב / עליית מחיר מקבלים SMS מראש, ולכן צפויה עלייה בפניות להחלפת חבילה. <b>אין צורך להתייעץ עם אחמ״ש</b> כשלקוח עולה לקו בעקבות עליית מחיר.</p><p><b>כלל אצבע: תמיד מציעים קודם את החבילה של 35 ₪ לדור 5.</b></p><table><tbody><tr><th>חבילה נוכחית</th><th>מחיר כיום</th><th>אחרי העלייה</th><th>הצעה 1</th><th>הצעה 2 (אם מתנגד)</th></tr><tr><td>wecomfreenewyear_4G</td><td>25 ₪</td><td>30 ₪</td><td>30 ₪</td><td>27.8 ₪</td></tr><tr><td>wecom_free4G</td><td>33 ₪</td><td>39.90 ₪</td><td>35 ₪</td><td>—</td></tr><tr><td>מנצחת 12</td><td>29.90 ₪</td><td>32.90 ₪</td><td>35 ₪</td><td>30 ₪</td></tr><tr><td>wecomfreenewyear_5G</td><td>32.90 ₪</td><td>37.90 ₪</td><td>35 ₪</td><td>—</td></tr><tr><td>חבילת חגים</td><td>29.90 ₪</td><td>32.90 ₪</td><td>35 ₪</td><td>30 ₪</td></tr><tr><td>עצמאות 2025</td><td>29.90 ₪</td><td>32.90 ₪</td><td>35 ₪</td><td>30 ₪</td></tr><tr><td>package_best_value_4G</td><td>23.90 ₪</td><td>32.90 ₪</td><td>30 ₪</td><td>27.8 ₪</td></tr><tr><td>wecomhome_4G</td><td>22.90 ₪</td><td>32.90 ₪</td><td>30 ₪</td><td>27.8 ₪</td></tr><tr><td>wecom500GB_5G_STAY</td><td>30 ₪</td><td>39.90 ₪</td><td>35 ₪</td><td>30 ₪</td></tr><tr><td>wecom500GB_4G_STAY</td><td>20 ₪</td><td>32.90 ₪</td><td>35 ₪</td><td>30 ₪</td></tr><tr><td>wecom500GB_5G</td><td>34 ₪</td><td>39.90 ₪</td><td>35 ₪</td><td>—</td></tr></tbody></table><h4>תסריטים לפי חבילה</h4><table><tbody><tr><th>חבילה</th><th>תסריט</th></tr><tr><td>wecomfreenewyear_4G</td><td>״נכון, שילמת 25 ₪. התוכנית הזו הסתיימה. ב-30 ₪ אני כבר מעבירה אותך מדור 4 לדור 5, עם 300GB גלישה, ובנוסף זו תוכנית ללא ניתוב נוסף.״</td></tr><tr><td>wecom_free4G</td><td>״הפער לעומת מה ששילמת היום הוא רק 2 ₪ בחודש. במקום להישאר בתוכנית הישנה בדור 4, אני יכולה להעביר אותך לתוכנית העדכנית בהתאם להצעה.״</td></tr><tr><td>מנצחת 12 / חבילת חגים / עצמאות 2025</td><td>״נכון, שילמת 29.90 ₪ במסגרת התוכנית הקודמת. היא כבר לא קיימת, אבל אני מציעה לעבור לדור 5 ללא הגבלת גלישה בעלות של 35 ₪, שזה רק עוד 2 ₪.״</td></tr><tr><td>wecomfreenewyear_5G</td><td>״אתה כבר בדור 5, וכאן מדובר בפער של 2.10 ₪ בלבד בחודש לעומת המחיר ששילמת עד היום – ללא הגבלת גלישה.״</td></tr><tr><td>package_best_value_4G / wecomhome_4G</td><td>״נכון, יש כאן עלייה לעומת המחיר שהיה לך, אבל אתה גם עובר מדור 4 לדור 5, מקבל 300GB, והתוכנית החדשה היא ללא ניתוב.״</td></tr><tr><td>wecom500GB_5G_STAY</td><td>״התוכנית הנוכחית שלך אמורה לעלות ל-39.90 ₪. במקום זה אני יכולה להעביר אותך ל-35 ₪, כך שהעלייה בפועל קטנה יותר, אבל אין בה הגבלת גלישה כלל, ובמקביל אתה עובר לתוכנית העדכנית ללא ניתוב.״</td></tr><tr><td>wecom500GB_4G_STAY</td><td>״נכון, עד היום שילמת 30 ₪, אבל עם אינטרנט מוגבל. ההצעה היא 35 ₪ עם דור 5, ללא הגבלת אינטרנט וללא ניתוב מחיר.״</td></tr><tr><td>wecom500GB_5G</td><td>״כאן מדובר בעלייה של שקל אחד בלבד בחודש – מ-34 ל-35 ₪ – עם הכפלה של כמות הגלישה וללא ניתוב מחיר.״</td></tr></tbody></table><h4>התנגדות נפוצה: \"תחזירו אותי לחבילה הקודמת\"</h4><p>״החבילה הקודמת כבר לא קיימת ואין כפל מבצעים. המבצע הוא חד-פעמי, ואחרי שניתן אי אפשר לשחזר אותו.״</p><h4>חריג – חבילת 22.90 ₪</h4><p>החבילה קיימת במערכת לנציגים, ומציעים אותה <b>רק אחרי איתות נטישה</b>, ורק אם: מדובר בלקוח מרובה מנויים / הלקוח מציין שקיבל הצעה אטרקטיבית יותר מחברה מתחרה / הלקוח מביע כוונה לעבור חברה. <b>⚠ חסר: האם צריכים להתקיים כל התנאים או אחד מהם</b></p><h3>בקרה</h3><ul><li>מאזינים לשיחות דרך <b>Glance</b>: בדיקה מלאה של כל פרטי הלקוח, היצמדות לאסקלציה ולתסריט, ולא יורדים מהשיחה בלי בדיקה מלאה ומענה לפי הטבלה.</li></ul><h3>תיעוד</h3><ul><li>לתעד: החבילה הקודמת והחדשה, ההצעות שהוצעו, וסיבת הבחירה.</li></ul><h3>לבדיקת העורך/ת – למחוק לפני פרסום</h3><ul><li>סתירה לבדיקה: כלל האצבע הוא \"תמיד מציעים 35 ₪ לדור 5\", אבל בטבלה הצעה 1 לחלק מהחבילות היא 30 ₪.</li><li>סתירה לבדיקה: הצעה 2 של 27.8 ₪ תואמת את wecomPlus 5G (27.80 ₪), שמוגדרת בטבלת החבילות (ספט׳ 2026) \"רק למנויים מנותקים לאחר 5 ימים\".</li><li>מומלץ לקשר למסמך החבילות הרשמי ולא לשכפל את טבלת החבילות כאן.</li></ul>"}};
window.dynamicDocs['kbd_r19'] = {"id":"kbd_r19","topic":"R-100 · צירוף קו / שדרוג 5G","cat":"plans","docType":"pdf","kind":"R","desc":"לקוח שמבקש קו נוסף או מעבר לדור 5: בדיקות, זיהוי, ומתי ואיך מעבירים למכירות.","tags":["מסלולים"],"owner":"","stages":[{"num":"1","title":"זיהוי","items":[{"text":"רכישת קווים חדשים = זיהוי מלא.","img":null},{"text":"רכישת מספר 051 חדש ללקוח שאין לו חשבון אצלנו = זיהוי מלא + צילום ת״ז בהתאם לתהליך.","img":null},{"text":"כשנדרש צילום ת״ז – להנחות את הלקוח להשחיר מראש כל פרט שאינו נדרש. גלויים נשארים רק: שם כפי שמופיע בתעודה ומספר ת״ז.","img":null}],"images":[]},{"num":"2","title":"שדרוג לדור 5","items":[{"text":"לבדוק שהמכשיר תומך ב-5G (מדריכי \"הגדרות דור 5\" באתר, לפי יצרן).","img":null},{"text":"שינוי התכנית לפי I-101 (פעם אחת בחודש קלנדרי). לקוחות ניתוב מחיר – תמיד קודם ההצעה של 35 ₪ לדור 5.","img":null},{"text":"אחרי המעבר – הגדרת 5G במכשיר (אייפון: הגדרות ← סלולרי ← אפשרויות נתונים סלולריים ← שיחות ונתונים ← 5G אוטו׳), ובדיקה.","img":null}],"images":[]},{"num":"3","title":"צירוף קו נוסף","items":[{"text":"לזוגות ומעלה קיימת חבילה משפחתית (wecom500GB 4G Family). (⚠ חסר: האם נציג שירות/תמיכה מוכר בעצמו, או תמיד מעביר למכירות)","img":null},{"text":"סים דאטה בלבד (טאבלט, מודם, מצלמה) – SIM DATA. המכשיר חייב לתמוך בהגדרת APN ידנית.","img":null}],"images":[]},{"num":"4","title":"העברה למכירות","items":[{"text":"יצירת ליד ב-CRM: מכירות ← לידים ← צור ליד.","img":null},{"text":"מילוי: סטטוס \"ליד תמיכה – העברה למכירות\", שם, טלפון נייד, הוקצה עבור, ומקור הליד \"ליד תמיכה\".","img":null},{"text":"העברת שיחה ישירה: שלוחה 333 (מכירות). (⚠ חסר: שעות המכירות – בצילום המסך מופיע \"עד 17:00\")","img":null},{"text":"גם כשהשיחה מועברת בלייב – חובה לפתוח ליד.","img":null}],"images":[]},{"num":"5","title":"תיעוד","items":[{"text":"לתעד: מה הלקוח ביקש, בדיקת תאימות המכשיר, ומספר הליד.","img":null}],"images":[]},{"num":"6","title":"לבדיקת העורך/ת – למחוק לפני פרסום","items":[{"text":"הקוד R-100 מוצע – לא במפה כמסמך נפרד. קשור ל-M-100 מסלולים וחבילות ול-M-120 הצטרפות","img":null}],"images":[]}],"track":{"state":"קיים חלקית","priority":"","gap":"טיוטת Word לבדיקה: 2 פערים מסומנים ⚠ חסר + 1 הערות לבדיקה","source":"טיוטות פריטי ידע / R-100 צירוף קו - שדרוג 5G.docx"},"status":"draft","source":{"name":"R-100 צירוף קו - שדרוג 5G.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/R-100%20%D7%A6%D7%99%D7%A8%D7%95%D7%A3%20%D7%A7%D7%95%20-%20%D7%A9%D7%93%D7%A8%D7%95%D7%92%205G.docx?web=1"}};
window.dynamicDocs['kbd_r20'] = {"id":"kbd_r20","topic":"I-102 · ניתוק קו","cat":"plans","docType":"pdf","kind":"I","desc":"טיפול בבקשת ניתוק: זיהוי, בירור הסיבה וניסיון שימור, ביצוע במועד, וחשבון סופי.","tags":["מסלולים"],"owner":"בת אל","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 1 פערים מסומנים ⚠ חסר + 2 הערות לבדיקה","source":"טיוטות פריטי ידע / I-102 ניתוק קו.docx"},"status":"draft","source":{"name":"I-102 ניתוק קו.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/I-102%20%D7%A0%D7%99%D7%AA%D7%95%D7%A7%20%D7%A7%D7%95.docx?web=1"},"body":{"html":"<h3>קודם כול</h3><p>לקוח מודיע שהוא עוזב = <b>איתות נטישה</b>. אין לסגור את השיחה או הצ׳אט כדי לסיים טיפול בלקוח מתוסכל. מצופה לברר את סיבת הנטישה, לבדוק פתרונות לפי ההנחיות, ולערב אחמ״ש אם אין מענה מספק.</p><h3>שלב 1 – זיהוי</h3><ul><li>לבקשת ניתוק נדרשים: <b>מספר הטלפון, מספר הזיהוי של בעל החשבון, 4 ספרות אחרונות של אמצעי התשלום, וכתובת מייל</b>.</li><li>בבקשה בכתב צריך לציין גם את מועד סיום ההתקשרות המבוקש.</li></ul><h3>שלב 2 – בירור הסיבה וניסיון שימור</h3><table><tbody><tr><th>הסיבה</th><th>מה מציעים</th></tr><tr><td>המחיר עלה / ניתוב מחיר</td><td>הצעות לפי I-101. חבילת 22.90 ₪ – רק אחרי איתות נטישה ובתנאים.</td></tr><tr><td>תקלה שלא נפתרה</td><td>לטפל בתקלה (המסלול הרלוונטי), ולערב אחמ״ש.</td></tr><tr><td>יוצא לתקופה / לא צריך את הקו זמנית</td><td>הקפאה (I-116) או שמירת מספר ב-wecomFreeze (4.90 ₪).</td></tr><tr><td>עובר לחברה אחרת עם המספר</td><td>הסבר: הניוד מתבצע דרך החברה החדשה, ואין צורך לבקש ניתוק (I-121).</td></tr></tbody></table><ul><li>ניסיון שימור – כן. <b>התניה, עיכוב או התשה של בקשת הניתוק – לא.</b> הלקוח רשאי להתנתק בכל עת, אלא אם הוסכם אחרת.</li><li>ראו גם נושא \"דיבאג נטישה\" באפליקציה.</li></ul><h3>שלב 3 – ביצוע</h3><ul><li>הניתוק מתבצע <b>במועד שהלקוח ביקש</b> (לא יום עסקים – ביום העסקים הבא). לא ציין מועד – <b>תוך יום עבודה אחד</b> מקבלת הבקשה או מאימותה, המאוחר מביניהם.</li><li><b>⚠ חסר: נתיב ביצוע הניתוק ב-CRM, ומי מבצע (נציג / צוות שימור)</b></li></ul><h4>ערוצים שבהם הלקוח יכול לבקש ניתוק</h4><ul><li>טלפון: ‎*5166 / 1-801-515151</li><li>מייל: nitook@we-com.co.il</li><li>פקס: 03-3094091</li><li>טופס מקוון או צ׳אט באתר</li><li>דואר: רח׳ יצחק רבין 1, פתח תקווה, 4925110</li></ul><h3>מה לומר ללקוח</h3><ul><li>בסיום ההתקשרות <b>כל השירותים מנותקים</b>.</li><li>הניתוק אינו מבטל חובות קיימים. תוכנית עם תקופת התחייבות – ייתכנו תשלומים בגלל סיום מוקדם.</li><li>התשלום הקבוע לחודש האחרון יחסי (לפי ימי שירות או היקף שימוש – הגבוה מביניהם).</li><li><b>החשבון הסופי נשלח תוך חודשיים</b> ממועד הניתוק.</li><li>אין התחייבות לשמור את המספר אחרי הניתוק.</li><li>עסקה חדשה (מכר מרחוק / נקודת מכירה) – אפשר לבטל תוך 14 יום לפי חוק הגנת הצרכן (ראו I-82).</li></ul><h3>תיעוד</h3><ul><li>לתעד: סיבת הניתוק, ההצעות שהוצעו ותגובת הלקוח, המועד המבוקש, ואישור הביצוע.</li></ul><h3>לבדיקת העורך/ת – למחוק לפני פרסום</h3><ul><li>לאשר את הניסוח \"ניסיון שימור כן, התניה לא\" מול הייעוץ המשפטי / נוהל השימור.</li><li>ממפת המסמכים: קשור ל-I-103 שימור לקוח</li></ul>"}};
window.dynamicDocs['kbd_o16'] = {"id":"kbd_o16","topic":"I-116 · הקפאת מנוי","cat":"plans","docType":"pdf","kind":"I","desc":"הפסקת שירות זמנית (הקפאה): תנאים, משך, עלות, וחזרה לפעילות. מול חלופת שמירת מספר (wecomFreeze).","tags":["מסלולים"],"owner":"בת אל","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 3 פערים מסומנים ⚠ חסר","source":"טיוטות פריטי ידע / I-116 הקפאת מנוי.docx"},"status":"draft","source":{"name":"I-116 הקפאת מנוי.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/I-116%20%D7%94%D7%A7%D7%A4%D7%90%D7%AA%20%D7%9E%D7%A0%D7%95%D7%99.docx?web=1"},"body":{"html":"<h3>תנאי ההקפאה</h3><table><tbody><tr><th>נושא</th><th>פירוט</th></tr><tr><td>כמה פעמים</td><td><b>אחת לשנה</b></td></tr><tr><td>משך</td><td><b>30 עד 90 ימים</b></td></tr><tr><td>עלות</td><td>ייתכן שכרוכה בתשלום, והוא נמסר ללקוח בעת הבקשה. <b>⚠ חסר: העלות בפועל</b></td></tr><tr><td>מועד ביצוע</td><td>במועד שהלקוח ביקש. לא ציין – תוך יום עבודה אחד מקבלת הבקשה או מאימותה</td></tr><tr><td>זיהוי</td><td>זיהוי מלא. החברה רשאית לדרוש גם את 4 הספרות האחרונות של אמצעי התשלום</td></tr><tr><td>חזרה לפעילות</td><td>אוטומטית בסוף התקופה, בלי צורך בהודעה. חזרה מוקדמת – בבקשה בכתב, תוך יום עבודה אחד</td></tr><tr><td>חובות</td><td>ההקפאה אינה גורעת מהחובה לשלם חובות קיימים</td></tr><tr><td>תעריף אחרי החזרה</td><td>לפי תעריפי התוכנית ותנאיה (אלא אם השתנו בזמן ההקפאה)</td></tr></tbody></table><h3>שלבים</h3><ol><li>זיהוי מלא.</li><li>לבדוק שלא בוצעה הקפאה בשנה האחרונה.</li><li>לסכם עם הלקוח מועד התחלה ומשך (30–90 יום), ולמסור את העלות.</li><li>ביצוע במערכת. <b>⚠ חסר: הנתיב ב-CRM</b></li><li>לאשר ללקוח את מועד החזרה האוטומטית.</li></ol><h3>חלופה: שמירת מספר – wecomFreeze</h3><p>בטבלת החבילות (ספט׳ 2026) מופיעה <b>wecomFreeze – הקפאת מספר – 4.90 ₪</b>. <b>⚠ חסר: מה ההבדל בינה לבין \"הפסקת שירות זמנית\", ולמי מציעים כל אחת – למשל שהייה ארוכה מ-90 יום</b></p><h3>תיעוד</h3><ul><li>לתעד: מועד התחלה, מועד חזרה, עלות שנמסרה, ואישור הלקוח.</li></ul>"}};
window.dynamicDocs['kbd_o17'] = {"id":"kbd_o17","topic":"I-112 · העברת בעלות","cat":"plans","docType":"pdf","kind":"I","desc":"העברת קו מבעלים אחד לאחר: מסמכים, זיהוי שני הצדדים, והשפעה על חיובים.","tags":["מסלולים"],"owner":"בת אל","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 3 פערים מסומנים ⚠ חסר","source":"טיוטות פריטי ידע / I-112 העברת בעלות.docx"},"status":"draft","source":{"name":"I-112 העברת בעלות.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/I-112%20%D7%94%D7%A2%D7%91%D7%A8%D7%AA%20%D7%91%D7%A2%D7%9C%D7%95%D7%AA.docx?web=1"},"body":{"html":"<h3>זיהוי ומסמכים</h3><ul><li>העברת בעלות = <b>זיהוי מלא של שני הצדדים</b>.</li><li>נדרש <b>צילום ת״ז + טופס חתום של שני הצדדים</b>, בהתאם לתהליך.</li><li>כשנדרש צילום ת״ז – להנחות את הלקוח להשחיר מראש כל פרט שאינו נדרש. גלויים נשארים רק: שם כפי שמופיע בתעודה ומספר ת״ז.</li><li><b>⚠ חסר: היכן נמצא טופס העברת הבעלות, ואיך הלקוחות מחזירים אותו (מייל / אתר / אפליקציה)</b></li></ul><h3>שלבים</h3><ol><li>זיהוי מלא של בעל הקו הנוכחי (מוסר) ושל הבעלים החדש (מקבל).</li><li>שליחת הטופס לשני הצדדים, וקבלת טופס חתום + צילומי ת״ז מושחרים.</li><li>אמצעי תשלום של הבעלים החדש (I-81).</li><li>ביצוע ההעברה. <b>⚠ חסר: מי מבצע (נציג / צוות back office), וזמן טיפול</b></li><li>עדכון שני הצדדים על מועד ההעברה.</li></ol><h3>השפעה על חיובים והטבות</h3><p><b>⚠ חסר: מה קורה לחוב פתוח של המוסר, להטבות ולתקופות התחייבות, ולחשבונית החודש שבו מתבצעת ההעברה.</b></p><p>בתנאים הכלליים: הלקוח אינו רשאי להעביר את זכויותיו לפי ההסכם לגורם אחר – לכן העברה נעשית <b>רק</b> בתהליך העברת הבעלות המסודר, ולא בהסכמה בין הלקוחות.</p><h3>תיעוד</h3><ul><li>לתעד: פרטי שני הצדדים, קבלת המסמכים, מועד ההעברה.</li></ul>"}};
window.dynamicDocs['kbd_o18'] = {"id":"kbd_o18","topic":"I-111 · עדכון פרטי לקוח","cat":"plans","docType":"pdf","kind":"I","desc":"עדכון כתובת, מייל, טלפון ליצירת קשר ופרטים נוספים – זיהוי, ומה חשוב לעדכן.","tags":["מסלולים"],"owner":"בת אל","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 4 פערים מסומנים ⚠ חסר","source":"טיוטות פריטי ידע / I-111 עדכון פרטי לקוח.docx"},"status":"draft","source":{"name":"I-111 עדכון פרטי לקוח.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/I-111%20%D7%A2%D7%93%D7%9B%D7%95%D7%9F%20%D7%A4%D7%A8%D7%98%D7%99%20%D7%9C%D7%A7%D7%95%D7%97.docx?web=1"},"body":{"html":"<h3>זיהוי</h3><ul><li>שינוי פרטי לקוח (לדוגמה כתובת / מייל) = <b>זיהוי מלא</b>. לא הושלם הזיהוי הנדרש = לא מוסרים מידע ולא מבצעים פעולה.</li></ul><h3>מה מעדכנים כאן</h3><ul><li>כתובת מגורים ו/או משלוח.</li><li>כתובת מייל (חשבוניות, קוד QR ל-eSIM).</li><li>טלפון ליצירת קשר.</li><li>אמצעי תשלום – <b>לא כאן</b>, אלא I-81.</li><li>שם / ת״ז – <b>⚠ חסר: האם אפשר לשנות, ואילו מסמכים נדרשים (למשל שינוי שם אחרי נישואין)</b></li></ul><h3>שלבים</h3><ol><li>זיהוי מלא.</li><li>עדכון השדה ב-CRM. <b>⚠ חסר: הנתיב, והאם השינוי נרשם ביומן אוטומטית</b></li><li>לחזור על הפרט החדש ללקוח לאישור.</li></ol><h3>למה זה חשוב</h3><ul><li>פרטים לא מעודכנים מונעים קבלת חשבוניות והודעות, ופוגעים ביכולת של שירותי החירום להגיע ללקוח.</li><li><b>משתמש קבוע</b> (בן משפחה או עובד שמשתמש בקו) – הלקוח צריך לעדכן אותנו כדי שנרשום אותו כמשתמש.</li><li>הלקוח יכול להגדיר <b>סיסמה</b> לקבלת מידע ולביצוע פעולות. <b>⚠ חסר: האם זה מיושם בפועל, ואיך הנציג מאמת סיסמה</b></li><li><b>איש קשר / מיופה כוח</b> שהלקוח מינה רשאי לבצע פעולות בשמו, אלא אם הוגבל. <b>⚠ חסר: איך רושמים איש קשר ב-CRM</b></li></ul><h3>תיעוד</h3><ul><li>לתעד: איזה פרט שונה (בלי לשכפל מידע רגיש בהערות).</li></ul>"}};
window.dynamicDocs['kbd_r21'] = {"id":"kbd_r21","topic":"I-121 · תהליך ניוד ל-wecom","cat":"plans","docType":"pdf","kind":"I","desc":"ניוד מספר אל wecom וממנה: איך זה עובד, זמנים, תנאים, ותקלות נפוצות.","tags":["מסלולים"],"owner":"אוריה","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 3 פערים מסומנים ⚠ חסר + 2 הערות לבדיקה","source":"טיוטות פריטי ידע / I-121 תהליך ניוד ל-wecom.docx"},"status":"draft","source":{"name":"I-121 תהליך ניוד ל-wecom.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/I-121%20%D7%AA%D7%94%D7%9C%D7%99%D7%9A%20%D7%A0%D7%99%D7%95%D7%93%20%D7%9C-wecom.docx?web=1"},"body":{"html":"<h3>זיהוי</h3><ul><li>איקטוב / ניוד קו = <b>זיהוי מלא</b>.</li></ul><h3>ניוד אל wecom</h3><ol><li>הלקוח מפעיל את הסים / eSIM בדף ההפעלה באתר (O-50 / O-51). <b>הפעלת הסים היא שמתחילה את הניוד.</b></li><li>בוחרים <b>ניוד מיידי</b> או <b>מועד עתידי</b> (תאריך ושעה).</li><li>קוד אימות נשלח לאימות הבעלות על הקו.</li><li>הניוד נמשך <b>עד 30 דקות</b>, אם התחיל בשעות הפעילות: א׳–ה׳ 08:00–21:00, ו׳ 08:00–13:00 (לא בשבת ובחגים).</li></ol><h3>מה חשוב שהלקוח ידע</h3><ul><li>בזמן הניוד יש <b>הפסקת שירות זמנית</b> במספר.</li><li>עובר <b>רק המספר</b>. תנאים והסכמות עם המפעיל הקודם לא עוברים איתו.</li><li>הניוד <b>לא מבטל את החובות</b> למפעיל הקודם – הלקוח צריך להסדיר אותם מולו.</li><li>הקו חייב להיות <b>בבעלות מלאה</b> של הלקוח, בלי מניעה חוקית או חוזית לניוד.</li><li>יש להשלים את הניוד <b>תוך 90 ימים</b> מיום העסקה (O-59).</li></ul><h3>ניוד החוצה מ-wecom</h3><ul><li>הניוד מתבצע דרך <b>החברה החדשה</b> – הלקוח לא צריך לבקש ניתוק מאיתנו.</li><li>בסיום הניוד ההתקשרות עם wecom מסתיימת. החשבון הסופי נשלח תוך חודשיים, וחובות קיימים נשארים בתוקף.</li><li>לקוח שמודיע שהוא עובר חברה = <b>איתות נטישה</b> – מבררים את הסיבה ומנסים לשמר (I-102).</li></ul><h3>תקלות נפוצות בניוד אל wecom</h3><table><tbody><tr><th>תקלה</th><th>מה בודקים</th></tr><tr><td>הניוד לא הושלם אחרי 30 דקות</td><td>האם התחיל בשעות הפעילות? אם לא – יבוצע ביום הפעילות הבא. <b>⚠ חסר: לאשר</b></td></tr><tr><td>הניוד נדחה</td><td>פרטי בעל הקו אצל המפעיל הקודם (ת״ז / ח.פ) לא תואמים? הקו לא בבעלות הלקוח? <b>⚠ חסר: קודי הדחייה ומשמעותם</b></td></tr><tr><td>קוד האימות לא מגיע</td><td>O-54, שלב 5</td></tr><tr><td>אין שירות אחרי שהניוד הושלם</td><td>O-53</td></tr></tbody></table><h3>תיעוד</h3><ul><li>לתעד: מועד הניוד שנבחר, סטטוס הניוד ב-CRM, והתקלה אם הייתה. <b>⚠ חסר: היכן רואים סטטוס ניוד ב-CRM</b></li></ul><h3>לבדיקת העורך/ת – למחוק לפני פרסום</h3><ul><li>ניוד קווים כשרים: לפי פרסומים, משרד התקשורת התיר מ-2022 לבני 18 ומעלה – לאשר אם רלוונטי ל-wecom.</li><li>ממפת המסמכים: הטיוטה כוללת גם ניוד החוצה (במפה I-124, ירון)</li></ul>"}};
window.dynamicDocs['kbd_r22'] = {"id":"kbd_r22","topic":"I-83 · חיובי חו״ל","cat":"intl","docType":"pdf","kind":"I","desc":"הסבר תעריפי שיחות, הודעות וגלישה בחו״ל, ובירור חיוב שהגיע אחרי החזרה לארץ.","tags":["חו\"ל"],"owner":"בת אל","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 1 פערים מסומנים ⚠ חסר","source":"טיוטות פריטי ידע / I-83 חיובי חו״ל.docx"},"status":"draft","source":{"name":"I-83 חיובי חו״ל.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/I-83%20%D7%97%D7%99%D7%95%D7%91%D7%99%20%D7%97%D7%95%D7%B4%D7%9C.docx?web=1"},"body":{"html":"<h3>קודם – להבחין: חו״ל או מב״ל?</h3><table><tbody><tr><th></th><th>שיחות בחו״ל (נדידה)</th><th>שיחות מב״ל</th></tr><tr><td>מה זה</td><td>שיחות יוצאות או נכנסות כשהלקוח <b>נמצא בחו״ל</b>, לפי עלות השיחות באותה מדינה</td><td>שיחות <b>מהארץ</b> למספר בחו״ל, דרך מפעיל בינלאומי</td></tr><tr><td>תמחור</td><td>לפי תעריפון הנדידה (בהמשך)</td><td>תוסף מב״ל 14.9 ₪ לחודש למדינות שבתוסף; מחוץ לתוסף – לפי המפעיל והיעד</td></tr></tbody></table><h3>תעריפי שיחות ו-SMS בחו״ל</h3><table><tbody><tr><th></th><th>חו״ל מוזל</th><th>תעריף רגיל (ללא חבילת חו״ל)</th></tr><tr><td>שיחה יוצאת / נכנסת ליעד מקומי או ישראלי</td><td>1.99 ₪ לדקה או חלק ממנה</td><td>19.90 ₪ לדקה או חלק ממנה</td></tr><tr><td>הודעת טקסט ליעד בינלאומי, מקומי או ישראלי</td><td>1.99 ₪ להודעה</td><td>3.50 ₪ להודעה</td></tr></tbody></table><ul><li>התעריף המוזל מתעדכן <b>אוטומטית</b> ללקוחות עם חבילת חו״ל weFly וללקוחות בתוכניות Global, במדינות שברשימה. <b>⚠ חסר: לאשר שהתעריפים בטבלה עדכניים</b></li><li><b>תמחור שיחות ותמיכה בגלישה הם שני דברים נפרדים</b> – בודקים כל אחד בנפרד, לפי המסמכים באתר (\"שימוש סלולרי בחו״ל\": מחירונים ומדינות כלולות לכל חבילה).</li><li>החבילות <b>אינן מיועדות להפלגות או לשימוש בים</b> – מחוץ לשטח הטריטוריאלי המכשיר אינו מחובר לרשת סלולרית.</li><li>ליד גבול ירדן או מצרים המכשיר עלול לנדוד אוטומטית לרשתות שם – החיוב נוסף ואינו כלול בתוכנית.</li><li>גם בלי פעולה יזומה יש צריכת נתונים ברקע (עדכונים, גיבויים, סנכרון).</li></ul><h3>חיוב שהגיע אחרי החזרה</h3><ul><li>חיובי נדידה עשויים להופיע <b>בחשבונית מאוחרת</b>, כי הרשומות מגיעות ממפעילים זרים. זה לא בהכרח שימוש חדש.</li><li>חיובי נדידה הם <b>ללא מע״מ</b>.</li></ul><h3>בירור</h3><ol><li>זיהוי מלא.</li><li>בשורת <b>\"שיחות\"</b> ב-CRM: האם נשלחה ללקוח הודעה עם קישור לתעריפים?</li><li>האם לקוח weFly / Global (תעריף מוזל) או ללא חבילה?</li><li>האם הנדידה בחו״ל פתוחה או סגורה באזור האישי?</li></ol><h3>מקרים שמחייבים העברה</h3><p>לקוח חויב על שיחות בחו״ל, <b>לא קיבל SMS בנושא</b>, ובאזור האישי <b>הנדידה בחו״ל סגורה</b> – <b>חובה לפתוח שיחת מנהל</b>, אחרי בדיקת הנתונים במערכות.</p><ul><li>לקוח חויב על שיחות <b>אחרי שביקש חסימה</b> – להעביר לשיחת מנהל.</li><li><b>הנחיה זמנית:</b> חסימת נדידה במערכות אינה מונעת בכל המקרים שיחות שמתבצעות ב-VoLTE. לכן <b>אין להבטיח ללקוח שהחסימה תמנע חיובי שיחות</b>, ו<b>אין לציין שמדובר בתקלה</b>.</li><li>לקוח מבקש חסימה מלאה של נדידה – הדרך הבטוחה היא <b>לכבות את קו wecom במכשיר</b> בזמן השהייה בחו״ל. להבהיר שכשהקו כבוי – שיחות, SMS וגלישה בקו הזה לא זמינים.</li><li>לקוח מבקש <b>רק</b> חסימת שיחות – להתייעץ עם אחמ״ש.</li></ul><h3>זיכוי</h3><ul><li>לפי I-82 (זיכויי רומינג ללא מע״מ).</li></ul>"}};
window.dynamicDocs['kbd_i12'] = {"id":"kbd_i12","topic":"I-115 · הרשאות, זיהוי וניהול מנוי","cat":"ops","docType":"pdf","kind":"I","desc":"איזה זיהוי נדרש לכל פעולה – בשירות ובתמיכה – וכללי האצבע. מה שקובע הוא הפעולה, לא המחלקה.","tags":["שירות"],"owner":"בת אל","stages":[],"track":{"state":"חסר","priority":"","gap":"טיוטת Word לבדיקה: 3 פערים מסומנים ⚠ חסר + 2 הערות לבדיקה","source":"טיוטות פריטי ידע / I-115 הרשאות, זיהוי וניהול מנוי.docx"},"status":"draft","source":{"name":"I-115 הרשאות, זיהוי וניהול מנוי.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/I-115%20%D7%94%D7%A8%D7%A9%D7%90%D7%95%D7%AA%2C%20%D7%96%D7%99%D7%94%D7%95%D7%99%20%D7%95%D7%A0%D7%99%D7%94%D7%95%D7%9C%20%D7%9E%D7%A0%D7%95%D7%99.docx?web=1"},"body":{"html":"<p><b>זיהוי לקוח – אפס חריגות.</b> שירות, תמיכה ומכירות – כולם, בלי יוצא מן הכלל, עובדים לפי טבלת הזיהוי. <b>מה שקובע הוא הפעולה – לא המחלקה.</b> אין זיהוי כנדרש = אין מסירת מידע ואין ביצוע פעולה.</p><h3>רמות זיהוי</h3><ul><li><b>זיהוי מלא</b> – <b>⚠ חסר: אילו פרטים בדיוק מרכיבים \"זיהוי מלא\" – למשל ת״ז + 4 ספרות אחרונות של אמצעי התשלום + פרט נוסף?</b></li><li><b>זיהוי חלקי</b> = אימות של אחד מהבאים: מספר ת״ז / 4 ספרות אחרונות של אמצעי התשלום / כתובת מייל או כתובת מגורים.</li><li><b>ללא זיהוי</b> – בירור וטיפול טכני בלבד, בלי שינוי בקו או בחשבון.</li></ul><h3>זיהוי לקוח בשירות</h3><table><tbody><tr><th>פעולה</th><th>זיהוי נדרש</th><th>דגשים</th></tr><tr><td>רכישת חבילת חו״ל</td><td>זיהוי מלא</td><td></td></tr><tr><td>פירוט שימושים ומסירת פרטים על החשבון</td><td>זיהוי מלא</td><td>אין למסור מידע לפני השלמת הזיהוי</td></tr><tr><td>העברת בעלות</td><td>זיהוי מלא של שני הצדדים</td><td>צילום ת״ז + טופס חתום של שני הצדדים לפי התהליך</td></tr><tr><td>רכישת קווים חדשים</td><td>זיהוי מלא</td><td></td></tr><tr><td>איקטוב קווים</td><td>זיהוי מלא</td><td></td></tr><tr><td>החלפת מספר</td><td>זיהוי מלא</td><td></td></tr><tr><td>עדכון אמצעי תשלום</td><td>זיהוי מלא</td><td></td></tr><tr><td>רכישת מספר 051 ללקוח בלי חשבון</td><td>זיהוי מלא</td><td>צילום ת״ז לפי התהליך המאושר</td></tr><tr><td>שינוי פרטי לקוח</td><td>זיהוי מלא</td><td></td></tr><tr><td>פתיחת שירותים – שיחות לחו״ל / SMS לחו״ל / תא קולי</td><td>זיהוי מלא</td><td></td></tr><tr><td>הפניית שיחות</td><td>זיהוי מלא</td><td></td></tr></tbody></table><p><b>כלל אצבע – שירות:</b> כל פעולה מחייבת זיהוי מלא, ולכן בעל החשבון עולה לקו ומאשר. אין לבצע את הפעולה בלי אישור בעל החשבון בשיחה.</p><h3>זיהוי לקוח בתמיכה – ללא זיהוי / חלקי</h3><table><tbody><tr><th>פעולה</th><th>זיהוי נדרש</th><th>דגשים</th></tr><tr><td>בדיקת תקלה ובירור מה הלקוח חווה</td><td>ללא זיהוי</td><td>בירור וטיפול בתקלה בלבד</td></tr><tr><td>בדיקות כלליות – אנטנות / גלישה / חסימות שיחות או SMS</td><td>ללא זיהוי</td><td>כל עוד לא מבוצע שינוי בקו או בחשבון</td></tr><tr><td>הגדרות מכשיר – APN / VoLTE / 5G / Wi-Fi Calling</td><td>ללא זיהוי</td><td></td></tr><tr><td>בדיקת תקינות קו – קוד 13/33 / פרופיל / רענון SIM</td><td>ללא זיהוי</td><td></td></tr><tr><td>שאלות כלליות בלי תפעול או מסירת מידע אישי</td><td>ללא זיהוי</td><td></td></tr><tr><td>אובדן מכשיר – חסימת שיחות יוצאות / SMS יוצא</td><td>זיהוי חלקי</td><td>פעולה למניעת נזק מיידי</td></tr></tbody></table><h3>זיהוי לקוח בתמיכה – זיהוי מלא</h3><table><tbody><tr><th>פעולה</th><th>זיהוי נדרש</th><th>דגשים</th></tr><tr><td>החלפת SIM / eSIM</td><td>זיהוי מלא</td><td>צילום ת״ז לפי התהליך</td></tr><tr><td>איקטוב / ניוד קו</td><td>זיהוי מלא</td><td></td></tr><tr><td>שינוי פרטי לקוח</td><td>זיהוי מלא</td><td>לדוגמה: כתובת / מייל</td></tr><tr><td>הוספת שירות בתשלום</td><td>זיהוי מלא</td><td>לדוגמה: תוסף שיחות מב״ל</td></tr><tr><td>שינוי תכנית</td><td>זיהוי מלא</td><td></td></tr><tr><td>פתיחת שירותים</td><td>זיהוי מלא</td><td>לדוגמה: שיחות לחו״ל / תא קולי</td></tr><tr><td>מכירת מספר 051 ללקוח חדש</td><td>זיהוי מלא</td><td>צילום ת״ז לפי התהליך</td></tr></tbody></table><p><b>כלל אצבע – תמיכה:</b> רוב התפעול הטכני – בלי זיהוי, כדי לא לפגוע בשירות. ברגע שנדרשת פעולה בקו – מבצעים קודם את הזיהוי הנדרש. פעולה שמחייבת זיהוי מלא והפונה אינו בעל החשבון – בעל החשבון עולה לקו ומאשר.</p><h3>צילום תעודת זהות</h3><ul><li>כשנדרש צילום ת״ז – להנחות את הלקוח להשחיר מראש כל פרט שאינו נדרש. גלויים נשארים רק: שם כפי שמופיע בתעודה ומספר ת״ז.</li></ul><h3>כלל זהב</h3><ul><li>בירור וטיפול טכני בלבד = אפשר להמשיך בלי זיהוי.</li><li>נדרשת פעולה בקו או בחשבון = עוצרים, מזהים, ורק אחר כך מבצעים.</li><li>לא אומת הלקוח = לא מוסרים מידע ולא מבצעים פעולה.</li></ul><h3>מקרים מיוחדים</h3><ul><li><b>בקשת ניתוק:</b> מספר טלפון, מספר זיהוי של בעל החשבון, 4 ספרות אחרונות של אמצעי התשלום, ומייל (I-102).</li><li><b>סיסמת לקוח:</b> הלקוח רשאי להגדיר סיסמה לקבלת מידע ולביצוע פעולות. <b>⚠ חסר: האם ואיך הנציג מאמת סיסמה</b></li><li><b>איש קשר / מיופה כוח</b> רשאי לפעול בשם הלקוח, אלא אם הוגבל. <b>⚠ חסר: איך מזהים איש קשר ומה הוא רשאי לבצע</b></li></ul><h3>לבדיקת העורך/ת – למחוק לפני פרסום</h3><ul><li>המקור מגדיר \"זיהוי חלקי\" אבל לא מגדיר \"זיהוי מלא\" – זה הפער החשוב במסמך.</li><li>ממפת המסמכים: במפה הקוד I-115 מופיע פעמיים (שורה 31 – קירה, שורה 43 – בת אל)</li></ul>"}};
window.dynamicDocs['kbd_i13'] = {"id":"kbd_i13","topic":"I-155 · ניתוב והעברת שיחה","cat":"ops","docType":"pdf","kind":"I","desc":"מתי ולאן מעבירים שיחה, מה מתעדים לפני העברה, ואיך מונעים העברה חוזרת.","tags":["שירות"],"owner":"","stages":[],"track":{"state":"קיים חלקית","priority":"","gap":"טיוטת Word לבדיקה: 2 פערים מסומנים ⚠ חסר + 1 הערות לבדיקה","source":"טיוטות פריטי ידע / I-155 ניתוב והעברת שיחה.docx"},"status":"draft","source":{"name":"I-155 ניתוב והעברת שיחה.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/I-155%20%D7%A0%D7%99%D7%AA%D7%95%D7%91%20%D7%95%D7%94%D7%A2%D7%91%D7%A8%D7%AA%20%D7%A9%D7%99%D7%97%D7%94.docx?web=1"},"body":{"html":"<h3>לאן מעבירים</h3><table><tbody><tr><th>המצב</th><th>לאן</th><th>דגשים</th></tr><tr><td>לקוח מתעניין ברכישה / קו נוסף / שדרוג</td><td>מכירות – <b>שלוחה 333</b></td><td>גם בהעברה בלייב – <b>חובה לפתוח ליד</b> (R-100)</td></tr><tr><td>חיוב שיחות בחו״ל בלי SMS ועם נדידה סגורה באזור האישי</td><td><b>שיחת מנהל</b> – חובה</td><td>אחרי בדיקת הנתונים במערכות</td></tr><tr><td>חיוב שיחות אחרי בקשת חסימה בחו״ל</td><td>שיחת מנהל</td><td>לא לציין שמדובר בתקלה</td></tr><tr><td>תקלת חו״ל שלא נפתרה בתפעול</td><td>מומחה – לפי הפורמט</td><td>רק אחרי תפעול מלא ומתועד</td></tr><tr><td>נתקעתם / לא בטוחים איך להמשיך</td><td>התייעצות עם אחמ״ש או מנהל</td><td></td></tr><tr><td>איתות נטישה בלי מענה מספק</td><td>לערב אחמ״ש</td><td>לא סוגרים שיחה או צ׳אט</td></tr><tr><td>תקלה רוחבית שזיהיתם</td><td>הצפה לאחמ״ש</td><td></td></tr><tr><td>תקלה רוחבית ידועה</td><td>לפי ההנחיה המסודרת שהופצה</td><td>אין לפתוח פניות – מערכות מידע מטפלים בה באופן גורף</td></tr><tr><td>החלפת חבילה שאינה על המדף</td><td>צוות נוק / מרת״מ</td><td><b>⚠ חסר: איך מעבירים</b></td></tr><tr><td>בקשת חוזה</td><td>פנייה ל-IT</td><td>החריג היחיד לפתיחת פנייה ל-IT</td></tr></tbody></table><p>⛔ <b>אין לפתוח פניות חדשות ל-IT</b> (מלבד בקשת חוזה). לקוח שממתין לתשובה מגורם שהעניין לא תלוי בו – זו פגיעה במקצועיות שלנו.</p><h3>לפני העברה – מה מתעדים</h3><ul><li>אילו בדיקות ותפעולים בוצעו ומה התוצאה של כל אחד.</li><li>מה הלקוח ביקש, ומה נאמר לו.</li><li>בתקלת חו״ל: אם אין ביומן השינויים תיעוד של <b>ריענון סים וריענון קו</b> (בהתנתקות ובהפעלה), המנוי <b>יחזור לתפעול נציג</b>, והמומחה לא יעזור.</li></ul><h3>מניעת העברה חוזרת</h3><ul><li>לא מעבירים לפני שהתפעול שבאחריות הנציג בוצע.</li><li><b>חשוב לזכור:</b> הסלמה בסוף שבוע מקפיצה את ההנדסה ומערכות המידע. הסלמה בלי תפעול = הקפצנו את כל המערך ביום חופש לחינם.</li><li>לא מסיימים טיפול לפני שמוודאים שניתן מענה לכל צורכי הלקוח – פנייה חוזרת היא מדד שדורש שיפור.</li></ul><h3>פרטים שחסרים</h3><p><b>⚠ חסר: שלוחות ותורים נוספים (שירות ↔ תמיכה, גבייה, שימור), שעות פעילות, והאם העברה היא \"חמה\" (עם הצגה) או \"קרה\".</b></p><h3>לבדיקת העורך/ת – למחוק לפני פרסום</h3><ul><li>הקוד I-155 מוצע – לא במפה. במפת שירות 360: \"העברת שיחה\" תחת תהליכי שירות רוחביים</li></ul>"}};
window.dynamicDocs['kbd_o19'] = {"id":"kbd_o19","topic":"O-156 · תיאום Callback / מעקב","cat":"ops","docType":"pdf","kind":"O","desc":"מתי פותחים חזרה ללקוח או פנייה למעקב, איך מנהלים אותה, וסגירת המעגל.","tags":["שירות"],"owner":"","stages":[],"track":{"state":"קיים חלקית","priority":"","gap":"טיוטת Word לבדיקה: 3 פערים מסומנים ⚠ חסר + 1 הערות לבדיקה","source":"טיוטות פריטי ידע / O-156 תיאום Callback - מעקב.docx"},"status":"draft","source":{"name":"O-156 תיאום Callback - מעקב.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/O-156%20%D7%AA%D7%99%D7%90%D7%95%D7%9D%20Callback%20-%20%D7%9E%D7%A2%D7%A7%D7%91.docx?web=1"},"body":{"groups":[{"title":"מתי פותחים Callback / מעקב","steps":[{"text":"פעולה שאי אפשר לבצע במהלך השיחה – למשל הגדרת APN (לא ניתן להגדיר APN במהלך שיחה).","img":null},{"text":"ממתינים לתוצאה: ניוד, סליקה חוזרת, רענון שדורש זמן.","img":null},{"text":"קו שנרכש ולא הופעל – מעקב לפני תום 90 הימים (O-59).","img":null},{"text":"הלקוח לא זמין להמשך הטיפול כרגע.","img":null}]},{"title":"איך פותחים","steps":[{"text":"(⚠ חסר: הכלי – משימה ב-CRM / פנייה פתוחה / יומן Callback)","img":null},{"text":"לרשום: מה בדיוק צריך לבצע בחזרה, מה כבר בוצע, ומספר טלפון לחזרה.","img":null},{"text":"לתאם עם הלקוח חלון זמן. (⚠ חסר: יעד זמן (SLA) לחזרה, ומספר ניסיונות לפני סגירה)","img":null}]},{"title":"אחריות אישית על פניות פתוחות","steps":[{"text":"אין להשאיר פניות פתוחות ללא טיפול. בזמן שיש זמינות – חובה לעבור על הפניות הפתוחות, לטפל בהן ולסגור בהתאם. האחריות למעקב ולטיפול בפניות היא של כל נציג.","img":null}]},{"title":"סגירת המעגל","steps":[{"text":"בחזרה – לבצע את הפעולה, לוודא שהבעיה נפתרה, ולוודא שאין צורך נוסף.","img":null},{"text":"המטרה: מענה מלא כבר בפנייה הראשונה, וצמצום פניות חוזרות.","img":null},{"text":"לא הצלחתם להשיג את הלקוח – (⚠ חסר: האם שולחים SMS, וכמה ניסיונות)","img":null}]},{"title":"תיעוד","steps":[{"text":"תיעוד הוא חובה, ומתבצע בזמן הניירת המיועד לכך – לא יותר מדקה וחצי. חריגה רק במקרה חריג ובאישור אחמ״ש.","img":null}]},{"title":"לבדיקת העורך/ת – למחוק לפני פרסום","steps":[{"text":"הקוד O-156 מוצע – לא במפה. במפת שירות 360: \"מעקב, שיחה חוזרת\" תחת תהליכי שירות רוחביים","img":null}]}]}};
window.dynamicDocs['kbd_i14'] = {"id":"kbd_i14","topic":"O-58 · בדיקת תאימות מכשיר ל-eSIM, 5G או VoLTE","cat":"sim","docType":"pdf","kind":"O","desc":"איך בודקים אם מכשיר תומך ב-VoLTE, ב-eSIM וב-5G, מה התנאים לשירות, ומה אומרים ללקוח כשהמכשיר לא נתמך.","tags":["SIM"],"owner":"","stages":[],"track":{"state":"קיים חלקית","priority":"","gap":"טיוטת Word לבדיקה: 4 פערים מסומנים ⚠ חסר + 2 הערות לבדיקה","source":"טיוטות פריטי ידע / O-58 בדיקת תאימות מכשיר ל-eSIM, 5G או VoLTE.docx"},"status":"draft","source":{"name":"O-58 בדיקת תאימות מכשיר ל-eSIM, 5G או VoLTE.docx","url":"https://marathon051-my.sharepoint.com/personal/liat_i_we-com_co_il/Documents/%D7%A9%D7%95%D7%9C%D7%97%D7%9F%20%D7%94%D7%A2%D7%91%D7%95%D7%93%D7%94/Kira/wecom-kb/%D7%98%D7%99%D7%95%D7%98%D7%95%D7%AA%20%D7%A4%D7%A8%D7%99%D7%98%D7%99%20%D7%99%D7%93%D7%A2/O-58%20%D7%91%D7%93%D7%99%D7%A7%D7%AA%20%D7%AA%D7%90%D7%99%D7%9E%D7%95%D7%AA%20%D7%9E%D7%9B%D7%A9%D7%99%D7%A8%20%D7%9C-eSIM%2C%205G%20%D7%90%D7%95%20VoLTE.docx?web=1"},"body":{"groups":[{"title":"הכלל החשוב","steps":[{"text":"שירות VoLTE ו-Wi-Fi Calling מובטח רק במכשיר מיבואן רשמי, שנקנה בארץ, ונמצא ברשימת הנתמכים. מכשיר מיבואן מקביל / משני או מכשיר שנקנה בחו״ל – אין התחייבות שהשירות יעבוד, גם אם הדגם מופיע ברשימה.","img":null},{"text":"זיהוי: בדיקת תאימות והגדרות מכשיר (APN / VoLTE / 5G / Wi-Fi Calling) – ללא זיהוי.","img":null}]},{"title":"מה זה ולמה זה קריטי","steps":[{"text":"VoLTE (Voice over LTE) – שיחות קוליות על רשת דור 4 במקום דור 3: איכות HD, הקמת שיחה מהירה, פחות ניתוקים ורעשי רקע.","img":null},{"text":"סגירת רשתות: משרד התקשורת החליט לסגור את רשתות דור 2 ודור 3 אצל כל המפעילים – קודם דור 2 ואחר כך דור 3. מכשיר שלא תומך בדור 4 ובמעלה (ו-VoLTE) לא יוכל להוציא ולקבל שיחות, ואולי גם לא SMS וגלישה. (⚠ חסר: מועדי הסגירה, כשיפורסמו)","img":null},{"text":"עלולים להיפגע גם: מכשירים ישנים, חלק מהמכשירים הכשרים, מערכות אזעקה, שערים חכמים ומכשירי IoT ישנים.","img":null},{"text":"ההצטרפות ל-VoLTE ללא עלות.","img":null}]},{"title":"איך בודקים","steps":[{"text":"המכשיר תומך? לפי רשימות הנתמכים בהמשך, ורשימת התאימות (PDF) בעמוד \"סגירת רשתות\" באתר. הרשימה עלולה להיות חלקית – כדאי לאמת גם באתר היצרן.","img":null},{"text":"מיבואן רשמי ונקנה בארץ?","img":null},{"text":"שירות VoLTE קיים ב-CRM?","img":null},{"text":"VoLTE פעיל במכשיר? – גם מכשיר תומך צריך שהשירות יהיה מופעל בהגדרות.","img":null},{"text":"הבדיקה הטובה ביותר: בזמן שיחה, האם המכשיר יורד מדור 4 לדור 3? נשאר על 4G/5G = VoLTE תקין. יורד ל-3G = תפעול VoLTE.","img":null}]},{"title":"הפעלה לפי יצרן","steps":[{"text":"Samsung: מכשירים שנקנו בישראל עם Android 15 ומעלה – אין מתג VoLTE, והשירות פעיל כברירת מחדל. בחלק מהמכשירים: הגדרות ← חיבורים ← רשתות תקשורת סלולריות ← הדלקת שיחות VoLTE.","img":null},{"text":"Xiaomi: ההפעלה אוטומטית. לא הופיע – לחייג ‎*#*#86583#*#*‎ (הפעלה / ביטול).","img":null},{"text":"iPhone: בדרך כלל אין מתג. לריענון: מצב טיסה הפעלה וכיבוי, ואז: הגדרות ← סלולרי ← אפשרויות נתונים סלולריים ← שיחות ונתונים ← מתג VoLTE.","img":null}]},{"title":"תפעול VoLTE (המכשיר יורד ל-3G בשיחה)","steps":[{"text":"בדיקת VoLTE: פעיל במכשיר / המכשיר תומך / השירות קיים ב-CRM.","img":null},{"text":"ביצוע ריענון: רענון דור 5 + רענון סים, רענון VoLTE, כיבוי והדלקה של המכשיר.","img":null},{"text":"בדיקה חוזרת: עדיין יורד ל-3G – ממשיכים ישירות לטופס רדיו. נשאר על 4G/5G – VoLTE תקין.","img":null}]},{"title":"מה קורה כשאין VoLTE","steps":[{"text":"גלישה בלבד / אין שיחות / שיחות מקוטעות / נראה כאילו אין קו.","img":null}]},{"title":"רשימות מכשירים נתמכי VoLTE","steps":[{"text":"הרשימות מתוך מצגת ההדרכה. (⚠ חסר: תאריך עדכון הרשימות, האם הן מלאות (למשל בסמסונג חסרות סדרות S24 ו-S25 הרגילות), ורשימה ליצרנים נוספים: Apple, Google Pixel, Motorola, Nokia, מכשירים כשרים)","img":null}]},{"title":"Samsung","steps":[{"text":"Galaxy A14 5G, A25 5G, A26 5G, A33 5G, A35 5G, A36 5G, A52 5G, A52s 5G, A53 5G, A54 5G, A55 5G, A56 5G, A73 5G · Galaxy M52 5G, M54 5G, M55 5G · Galaxy S20 FE 5G, S21 5G, S21+ 5G, S21 Ultra 5G, S21 FE 5G, S22 5G, S22+ 5G, S22 Ultra 5G, S23 5G, S23+ 5G, S23 Ultra 5G, S23 FE 5G, S24 FE 5G, S25 FE 5G · Galaxy Note20 Ultra 5G · Galaxy Z Flip3 5G, Z Flip4, Z Flip5, Z Flip6, Z Flip7 5G · Galaxy Z Fold2 5G, Z Fold3 5G, Z Fold4, Z Fold5, Z Fold6, Z Fold7 5G","img":null}]},{"title":"Xiaomi / Redmi / POCO","steps":[{"text":"Xiaomi 12, 12 Lite, 12 Pro, 12T, 12T Pro, 13, 13 Lite, 13 Pro, 13T, 13T Pro, 14, 14 Ultra (5G), 14T (5G), 14T Pro (5G), 15, 15 Ultra, 15T 5G, 15T Pro 5G, 17 5G, 17 Ultra 5G, Mix Flip (5G) · Redmi 12, 12 5G, 12 NFC, 12C, 13, 13 (NFC), 13C, 13C 5G, 13X, 13 Pro (5G), 13 Pro+ (5G), 14C, 14C (NFC), 15, 15 5G, 15C, 15C 5G, A2, A2+, A3, A5 · Redmi Note 12, 12 Pro, 12 Pro (5G), 12 Pro+ (5G), 12S, 13, 13 Pro (4G), 14, 14 NFC (4G), 14 (5G), 14 Pro (4G), 14 Pro (5G), 14 Pro+ (5G), 15, 15 5G, 15 Pro, 15 Pro 5G, 15 Pro+ (5G) · Redmi Pad (8.7\") 4G, Pad 2 4G, Pad 2 Pro 5G, Pad Pro (5G) · POCO C51, C61, C65, C71, C75, F5, F5 Pro, F6, F6 Pro, F7, F7 Pro, F7 Ultra, F8 5G, F8 Pro 5G, F8 Ultra 5G, M6, M6 Pro, M6 Pro 5G, M7, M7 Plus 5G, M7 Pro 5G, M8 5G, M8 Pro 5G, X5 (5G), X5 Pro (5G), X6 5G, X6 Pro 5G, X7 Pro","img":null}]},{"title":"OPPO","steps":[{"text":"דגם: A5, A5 PRO, A6 PRO, A6X, A18, A58, A78 · VoLTE: כן · eSIM: –","img":null},{"text":"דגם: Reno 8T, Reno 10, Reno 10 PRO, Reno 11, Reno 11F, Reno 12, Reno 12F, Reno 13, Reno 13F · VoLTE: כן · eSIM: –","img":null},{"text":"דגם: Reno 14, Reno 14F, Reno 15, Reno 15F · VoLTE: כן · eSIM: כן","img":null},{"text":"דגם: Find X5, Find X8 pro, Find X9 pro · VoLTE: כן · eSIM: כן","img":null}]},{"title":"eSIM","steps":[{"text":"אייפון: הגדרות ← סלולרי – אם מופיע \"הוסף תכנית סלולרית\", המכשיר תומך.","img":null},{"text":"אנדרואיד: הגדרות ← חיבורים ← מנהל כרטיסי SIM – אם מופיע \"הוספת חבילה סלולרית\", המכשיר תומך.","img":null},{"text":"רשימת המכשירים התומכים – באתר: מדריכים ושירות עצמי ← הגדרות eSIM (PDF).","img":null},{"text":"תנאי נוסף: המכשיר אינו חסום למפעילים זרים.","img":null},{"text":"התקנה והפעלה – O-51. מעבר בין SIM ל-eSIM – O-52.","img":null}]},{"title":"5G","steps":[{"text":"נדרשים גם מכשיר שתומך ב-5G וגם תכנית דור 5. שדרוג תכנית – R-100.","img":null},{"text":"מדריכי הגדרה ל-5G (אנדרואיד ואייפון) – באתר: מדריכים ושירות עצמי ← הגדרות דור 5.","img":null},{"text":"אייפון: הגדרות ← סלולרי ← אפשרויות נתונים סלולריים ← שיחות ונתונים ← \"5G אוטו׳\" / \"5G פעיל\" / LTE.","img":null},{"text":"(⚠ חסר: רשימת מכשירים נתמכי 5G, והאם מכשיר מיבואן מקביל נתמך ב-5G)","img":null}]},{"title":"Wi-Fi Calling","steps":[{"text":"גם כאן: מכשיר שלא נקנה בישראל ו/או אינו מיבואן רשמי – אין התחייבות שהשירות יעבוד.","img":null},{"text":"מכשיר שגרסת התוכנה שלו לא ברשימת התמיכה – השירות לא יהיה זמין.","img":null},{"text":"הזמינות תלויה בשילוב של דגם, גרסת מערכת הפעלה והגדרות יצרן – ייתכנו הבדלים בין מכשירים זהים ממקורות שונים.","img":null}]},{"title":"תסריט: המכשיר לא תומך ב-VoLTE","steps":[{"text":"״אני רוצה לעדכן אותך במשהו חשוב לגבי המכשיר שלך. המכשיר שלך לא תומך בטכנולוגיית VoLTE, שהיא הטכנולוגיה שעליה מתבצעות היום שיחות.״","img":null},{"text":"״כרגע זה עדיין עובד בגלל רשתות ישנות (דור 2 ו-3), אבל משרד התקשורת כבר התחיל לסגור אותן בהדרגה. ברגע שייסגרו לחלוטין, לא תהיה אפשרות להוציא או לקבל שיחות מהמכשיר הזה בכלל.״","img":null},{"text":"״זה לא מיידי, אבל כן משהו שחשוב להיערך אליו מראש, ולכן אני ממליץ/ה לשקול מעבר למכשיר תומך, כדי להימנע מניתוקים ולהמשיך ליהנות משירות מלא.״","img":null}]},{"title":"פרטים נוספים לבדיקה","steps":[{"text":"⚠ חסר: באתר wecom מופיע המספר ‎*0051‎ למכשירים שאינם ברשימת התאימות – מה הוא עושה ומתי מפנים אליו.","img":null}]},{"title":"לבדיקת העורך/ת – למחוק לפני פרסום","steps":[{"text":"אין בישראל מידע רשמי על מועדי סגירת רשתות דור 2/3 בעמוד של wecom – לעדכן כשמשרד התקשורת יפרסם.","img":null},{"text":"ממפת המסמכים: קשור גם ל-O-44 (בדיקת תאימות מכשיר ל-VoLTE, אצל שחר)","img":null}]}]}};
